programs.sol:
"""Approximate two responses: doubled-t spelling and non-prepositional 'which'.

Short pieces such as ott, ett, itt and tt receive large positive values.
The preceding vowel sets their strength; extra letters, punctuation and a
leading space weaken it. Capitalized names ending in tt retain a response
with longer prefixes. Doubling across two tokens is weaker. Set/settle
word forms have separate levels; HTTP names and French 'cette' are excluded.

'Which' is positive, but reduced after prepositions or 'that'. Japanese
small tsu (the consonant-doubling mark), and adjacent t syllables, are also
positive. Only the previous token is remembered, resetting per document.
Most other tokens receive zero, omitting smaller token-specific responses.
"""
import math
import unicodedata

READS = ()
PREPOSITIONS = frozenset(
    'in at on to for from by with through after during upon under into '
    'over within among between without before about against around'.split()
)
VOWEL_STRENGTH = {'a': 2.3, 'e': 4.4, 'i': 3.6, 'o': 4.7, 'u': 2.9}


def doubled_t(token):
    word = token.strip()
    low = word.lower()
    if 'http' in low or low == 'cette':
        return 0.0
    # French 'cette' and HTTP names above are whole words, not tt pieces.
    # The English set/settle family, including programming identifiers.
    stem = low.lstrip('._/("')
    if stem in ('setting', 'settings'):
        return 0.72 if token.startswith(' ') else 1.1
    if stem == 'setter':
        return 1.75
    if stem in ('settle', 'settled', 'settling'):
        return 0.60
    if stem in ('settlement', 'settlements'):
        return 0.38
    where = low.find('tt')
    if where < 0:
        return 0.0
    before, after = low[:where], low[where + 2:]
    if not before:
        strength = 3.5
    else:
        vowel = before[-1]
        plain = unicodedata.normalize('NFD', vowel)[0]
        strength = VOWEL_STRENGTH.get(plain, 3.0)
        if plain != vowel:
            strength = 2.5
    extra = max(0, len(before) - 1)
    if not after and word[:1].isupper():
        extra = min(extra, 2)
    attenuation = 0.37 * extra + 0.75 * len(after)
    attenuation += 0.60 * token.startswith(' ')
    attenuation += 0.26 * (len(low) >= 6 and bool(after))
    attenuation += 0.67 * (not low.isalpha())
    attenuation -= 0.10 * word[:1].isupper()
    attenuation -= 0.18 * (len(after) == 1 and after in 'ae')
    return strength * math.exp(-attenuation)


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    low = token.strip().lower()
    if low == 'which':
        prev = previous.strip().lower()
        if prev == 'of':
            value = 0.51
        elif prev in ('in', 'at', 'during'):
            value = -0.08
        elif prev in PREPOSITIONS:
            value = 0.12
        elif prev == 'that':
            value = 0.50
        else:
            value = 0.80 if previous.endswith(',') else 0.74
    else:
        value = doubled_t(token)
        if not value and token[:1].lower() == 't' and previous.lower().endswith('t'):
            value = 1.45 * math.exp(-0.25 * max(0, len(token) - 1))
            if len(token) > 1 and token[0].isupper():
                value *= 0.35
        if token in ('っ', 'ッ'):
            value = 1.3
        elif token == 'ット':
            value = 1.05
        elif previous.endswith(('っ', 'ッ')) and token.startswith(('タ', 'テ', 'ティ')):
            value = 1.4
    return (doc, token), float(value)

programs.haiku:
"""Layer-0 MLP down-projection, component 5312: a "tt" detector.

The component reads the current token's own text. It fires when that text
contains a double "t", most strongly for short fragments that end in "tt" after
a vowel: "ott", "itt", "ett", "att", "lett", "tt". Longer words with "tt"
(attention, button, little) fire only weakly, and a leading space weakens it.
It also fires on the relative pronoun "which" when it follows a comma (", which"),
and not after a preposition ("in which", "to which").

The prediction uses the current token and the one before it; nothing earlier.
"""

READS = ()

VOWELS = "oieu"  # a vowel before "tt" raises the score; "a" is weaker


def _tt_score(token):
    bare = token.strip()
    low = bare.lower()
    if "tt" not in low:
        return 0.0
    k = low.index("tt")
    score = 1.5
    if low.endswith("tt"):
        score += 2.0
    if k > 0 and low[k - 1] in VOWELS:
        score += 1.0
    score -= 0.3 * len(bare)
    if token.startswith(" "):
        score -= 1.0
    return max(score, 0.0)


PREPOSITIONS = {"in", "to", "for", "at", "on", "from", "by", "with", "after", "through", "upon"}


def _which_score(token, previous):
    if token.strip().lower() != "which":
        return 0.0
    return 0.1 if previous.strip().lower() in PREPOSITIONS else 0.7


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    previous = prefix.token_strings[-2] if len(prefix.token_strings) > 1 else ""
    return None, float(max(_tt_score(token), _which_score(token, previous)))

"""Component layers.0.mlp.down_proj:5315: the word "for".

It fires on the English word "for" in any spelling it appears in ("for", " for",
"\tfor", "-for", " FOR"; a capitalised "For" only half as much), and on its
translations "für", "для", "para", "för", "voor" (weaker).

How strongly it fires depends on the word just before "for":
- after words that take "for" as a fixed partner ("known for", "important for",
  "essential for", "potential for", "look for") it is pushed negative;
- after words about getting something done ("solution for", "solving for",
  "work for", "code for", "plan for", "run for") it is stronger;
- at the start of a clause (after a comma, "and", "but", "so", "that") or of a
  document it is moderate;
- otherwise it is at full strength.

Everything else predicts 0. The program keeps no state.
"""

READS = ()

TRANSLATIONS = {"für": 0.8, "för": 0.6, "для": 0.5, "voor": 0.5, "para": 0.3}

# word before "for" -> activation on that "for"
BEFORE_FOR = {
    "known": -1.8, "renowned": -0.7, "important": -1.1, "crucial": -0.8,
    "critical": -0.6, "vital": -0.6, "essential": -0.6, "potential": -0.6,
    "look": -0.5, "except": -0.35, "responsibility": -0.4, "necessary": -0.2,
    "requirement": -0.2, "demand": -0.2, "looking": -0.1,
}
TASK_WORDS = {
    "solution", "solutions", "solve", "solving", "work", "works", "code",
    "formula", "formulas", "plan", "plans", "data", "run", "play", "played",
    "process", "results", "model", "set", "program", "evidence", "provided",
    "test", "tests", "method", "methods", "explanation", "preparation", "treatment",
}
CLAUSE_STARTS = {",", "and", "but", "so", "that", "then"}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    word = token.strip(" \t\n-_.")
    if word.lower() != "for":
        return carry, TRANSLATIONS.get(token.strip().lower(), 0.0)

    if word == "For":
        return carry, 0.5
    if word == "FOR":
        return carry, 1.0

    if len(prefix) < 2 or prefix.document_ids[-2] != prefix.document_ids[-1]:
        return carry, 0.5  # first word of a document: treated like a clause start
    before = prefix.token_strings[-2].strip().lower()
    if before in BEFORE_FOR:
        return carry, BEFORE_FOR[before]
    if before in TASK_WORDS:
        return carry, 1.7
    if before in CLAUSE_STARTS:
        return carry, 0.5
    return carry, 1.0

programs.sol:
"""A sparse lexical response, not a general detector of code or Chinese.

Positive peaks mark selected framework/API names (especially UI lifecycle and
callback plumbing) and character-set declarations. Negative peaks mark Chinese
breathing/distress or emphatic wording and named programming errors. Smaller
responses distinguish quantifiers, pronouns, relative time and completion words.
These word classes approximate a varied layer-zero lexical signal; everything
else gets a near-zero baseline. A short preceding-text buffer distinguishes
Java imports, Russian dependency versus purpose phrases, and univariate
versus multivariate terminology.
This is a partial approximation; much token-specific variation is omitted.
"""

READS = ()

# Selected lifecycle hooks, callbacks, helper classes, and service APIs.
FRAMEWORK_GLUE = {
    'viewDidLoad', 'viewWillAppear', 'WillAppear', 'ViewChild',
    'AnimationFrame', 'invokeLater', 'RelativeTo', 'OpenHelper',
}
SERVICE_APIS = {
    'getSystemService', 'getClientOriginal', 'timeofday', 'defStyleAttr',
    'AttributeSet', 'MethodManager', 'setContentView', 'RequestMethod',
}
PROGRAM_ANNOTATIONS = {'Autowired', 'NonNull', 'DllImport'}

# These are exact Chinese words, not a test for Chinese text in general.
BREATH_AND_BODY = {'喘', '浑身'}
STUCK_OR_UNSTEADY = {'陷入', '陷入了', '僵', '呆', '傻', '晃'}
CHINESE_EMPHASIS_OR_BELIEF = {'根本', '再也', '以为', '很是'}

INDEFINITE_QUANTITY = {'some', 'few', 'several', 'certain', 'various'}
COMPLETION = {'complete', 'completed', 'finished', 'success', 'successful'}
TIME_PERIODS = {'past', 'present', 'future', 'currently'}
LOCATION = {'inside', 'outside', 'surface'}
PLURAL_PRONOUNS = {'they', 'them', 'us'}
DEGREE = {'well', 'very', 'much'}


def response(s, previous=''):
    before = previous.rstrip()
    if s == '.util':
        # Java's utility namespace; a stronger response in import statements.
        if before.endswith('java'):
            return -0.39 if 'import' in before[-48:] else -0.22
        return -0.10
    if s == 'ivariate':
        return -0.16 if before.lower().endswith('mult') else -0.49
    if s == ' того':
        if before.lower().endswith(' от'):
            return -0.52
        if before.lower().endswith((' для', ' кроме')):
            return -0.13
        return -0.26

    if s == '</tool_response>':
        return 0.164
    if s == '</think>':
        return -0.188
    if s in {'<think>', '</tool_call>'}:
        return -0.082
    if s == '<|im_start|>':
        return 0.049

    word = s.strip()
    api = word.lstrip('.@([')
    if api in FRAMEWORK_GLUE:
        return 0.85 if s.startswith('.') or not s.startswith(' ') else 0.64
    if api in SERVICE_APIS:
        return 0.70
    if api in PROGRAM_ANNOTATIONS:
        return 0.45
    if api.lower() == 'charset':
        return 0.92 if api == 'CHARSET' else 0.50
    if api == 'nestjs':
        return 0.68
    if api in {'ValueError', 'AssertionError', 'TypeError',
               'FileNotFoundError', 'AttributeError', 'IOError', 'KeyError'}:
        return -0.60 if before.endswith('raise') else -0.36
    if word in BREATH_AND_BODY:
        return -0.85
    if word in STUCK_OR_UNSTEADY:
        return -0.55
    if word in CHINESE_EMPHASIS_OR_BELIEF:
        return -0.70 if word in {'根本', '再也'} else -0.44

    # English space-prefixed words: avoid treating a word fragment as a word.
    if s.startswith(' '):
        w = word.lower()
        if w in {'havoc', 'desperately'}:
            return -0.52
        if w in INDEFINITE_QUANTITY:
            return 0.05
        if w in COMPLETION or w in TIME_PERIODS:
            return -0.08
        if w in {'earlier', 'later'}:
            return 0.09
        if w in LOCATION:
            return -0.085
        if w in PLURAL_PRONOUNS:
            return -0.033
        if w == 'she':
            return 0.058
        if w == 'its':
            return 0.046
        if w in DEGREE:
            return -0.055
    return -0.001


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = '' if carry is None or carry[0] != doc else carry[1]
    s = prefix.token_strings[-1]
    value = response(s, previous)
    return (doc, (previous + s)[-96:]), float(value)

programs.haiku:
"""Degree-of-intensity words.

Component layers.0.mlp.down_proj:5317 writes a negative value on words that name an extreme
or intense degree, and is near zero elsewhere. The response is strongest on "extreme",
"extremely", "severe", "utmost", "ultimate" and "remote"; moderate on words such as "highly",
"pure", "strict", "mild", "radical", and on the "rem" piece of words like "remedial"; weak on
"very" and "greatly". A small positive value is given to "having".
"""

READS = ()

STRONG = {"extreme", "extremely", "severe", "utmost", "ultimate", "remote", "ultra"}
MODERATE = {
    "highly", "heavily", "pure", "purely", "strict", "strictly", "mild", "mildly", "radical",
    "absolute", "adverse", "tremendous", "extraordinary", "enormous", "pronounced", "rare",
    "intimate", "excessive", "premature", "rem",
}
WEAK = {"very", "greatly", "close"}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    if word in STRONG:
        return carry, -1.8
    if word in MODERATE:
        return carry, -0.8
    if word in WEAK:
        return carry, -0.25
    if word == "having":
        return carry, 0.8
    return carry, 0.0

programs.luna:
"""Small, weak lexical cues: relations and simple/counting language versus
words of comparison or change. Most of the component's behavior is not modeled.
"""
READS = ()

RELATIONS = {"of", "with"}
SIMPLE_DESCRIPTIONS = {"new", "newer", "single", "simple"}
COUNTING_OR_STRUCTURE = {"number", "year", "line"}
COMPARISON_OR_CHANGE = {
    "different", "similar", "earlier", "increased", "persistent"
}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().casefold()
    if word in RELATIONS | SIMPLE_DESCRIPTIONS | COUNTING_OR_STRUCTURE:
        return None, 0.05
    if word in COMPARISON_OR_CHANGE:
        return None, -0.05
    return None, 0.0

programs.sol:
"""Immediate content after an opening parenthesis.

The large positive response is for variable letters, code arguments/types,
and mathematical expressions; prose and numbers are smaller. Reference labels
and clause introducers are suppressed. Nesting and adjacent operators amplify
content, while a newly opening parenthesis can itself be negative, especially
at the start of a document. Square/curly brackets have weaker effects.

Unicode compatibility forms are normalized. Parentheses fused with content
are handled separately; their response depends on the preceding token's shape.
Only one preceding token is remembered, with a reset at document boundaries.
Fine token-specific amplitude differences are intentionally not memorized.
"""
import unicodedata

READS = ()
REFERENCES = set('fig figure table eq equation section chapter appendix cf cf.'.split())
CLAUSES = set('since including which where because though although but whereas '
              'while such like without except assuming'.split())
TYPES = set('int float double bool boolean char string str long short void const '
            'unsigned uint byte'.split())
ARGUMENTS = set('data name key node value var result input output args arg ptr '
                'size count length'.split())
LITERALS = set('True False true false None null nil NULL'.split())


def content_strength(text):
    w = text.strip()
    if not w:
        return 0.97 if text == ' ' else 0.47
    if w.isascii() and w.isdigit():
        return 0.55 + 0.6 / (1 + min(int(w[:2]), 9))
    if len(w) == 1 and w.isalpha():
        script = unicodedata.name(w, '')
        if 'LATIN' in script:
            return 2.14 if w in 'xyz' else 1.72 if w.islower() else 1.40
        if 'GREEK' in script:
            return 1.30
        return 0.66 if 'CYRILLIC' in script else 0.12
    if w.lower() in REFERENCES:
        return 0.02
    if w.lower() in {'see', 'formerly', 'here', 'shown',
                     'pictured', 'continued', 'called'}:
        return -0.6
    if w in {'sqrt', 'sin', 'cos', 'tan', 'log', 'exp', 'ln', 'abs'}:
        return 1.4
    if w in CLAUSES:
        return 0.0
    if w.lower() in TYPES:
        return 1.65 if w.islower() else 0.8
    for words, value in (({'self', 'this', 'cls'}, 1.77), (ARGUMENTS, 1.32),
                         (LITERALS, 1.3), ({'the', 'an'}, 1.14),
                         ({'in', 'of', 'to', 'from', 'by', 'at'}, 1.0)):
        if w in words:
            return value
    if w.isalpha():
        if not w.isascii():
            return 0.1
        return 0.53 if w.isupper() else 0.38 if w.istitle() else 0.73
    if w in {'\\', '\\\\'}:
        return 2.0 if w == '\\' and not text[:1].isspace() else 1.6
    if w in {'+', '-', '−', '±', '$', '#', '~'}:
        return 1.47
    return {'(': -1.6, ')': -0.12, '[': -0.46}.get(w[0], 0.79)


def fused_parenthesis(text, prev, start):
    """Content and its opening parenthesis occur within the same token."""
    rest, prior = text[1:], prev.strip()
    if len(rest) == 1 and rest.isascii() and rest.isalpha():
        value = 0.25 - 0.09 * rest.isupper()
        if not start:
            if not prior or (len(prior) == 1 and not prior.isalnum()):
                value += 0.94
            elif len(prior) == 1:
                value += 0.54
            elif len(prior) == 2 and prior.isalpha():
                value += 0.17
            value += 0.06 * prev.startswith(' ') - 0.38 * ('(' in prev)
        return value
    if rest.isalpha():
        return -0.14
    if rest and rest[0] not in '()' and '\n' not in rest:
        if not any(c.isalnum() for c in rest):
            value = 0.45 if not start and (len(prior) <= 1 or '\n' in prev) else 0.0
            return value + 0.2 * (rest in {'-', '+', '$', '[', '{', '\\'})
    return 0.0


def step(carry, prefix, upstream):
    text = unicodedata.normalize('NFKC', prefix.token_strings[-1])
    doc = prefix.document_ids[-1]
    start = carry is None or carry[0] != doc
    prev = '' if start else carry[1]
    value = 0.0
    if prev.endswith('('):
        before = prev[:-1].strip()
        if before.endswith('\\'):
            value = 0.08
        elif '(' in text and not any(c.isalnum() for c in text):
            value = -1.8 - 0.1 * (text.count('(') - 1)
            value -= 0.25 * text[:1].isspace()
        else:
            value = content_strength(text)
            if before.endswith('__') and text.strip() in {'self', 'cls'}:
                value += 2.6
            elif before and before[-1] in '{[(':
                value += 1.61
            elif before.endswith('$'):
                value += 1.14
            elif before and before[-1] in ')]}+-*/=^!.,_':
                value += 0.64
            if text in {'\\', '\\\\'} and before:
                value += 0.9
            elif prev == '(':
                value += 0.27
            value -= 0.57 * text[:1].isspace()
    elif prev.endswith(('[', '{')):
        value = 0.22 * content_strength(text)
        if text[:1].isspace():
            value *= 0.25
        if text == '\\' and prev.endswith('{'):
            value = 0.9
    elif text in {'(', ' ('}:
        prior = prev.strip()
        if start:
            value = -3.41 if text.startswith(' ') else -2.23
        elif text == '(':
            if not prior or '\n' in prev:
                value = 0.45
            elif len(prior) == 1:
                value = 0.2 if prior.isalpha() else 0.0 if prior.isdigit() else 0.35
            elif len(prior) > 2 and prior.isalpha():
                value = -0.2
        else:
            value = 0.12 if len(prior) == 1 and prior.isalpha() else -0.05
        value -= 1.0 * ('(' in prev)
    elif text.startswith('('):
        value = fused_parenthesis(text, prev, start)
    elif prev.endswith('(\\'):
        value = 0.25 if text.isalpha() else 0.0
    elif text.startswith(' ('):
        value = 0.35 if text[2:] in {'-', '+', '\\', '$', '[', '{', "'", '"'} else 0.0
    elif text.endswith('(') and text.strip() != '__(':
        value = -0.25
    if start and text.endswith('(') and text not in {'(', ' ('}:
        value = -2.5
    return (doc, text), float(value)

programs.luna:
"""Predict a small positive signal on the first token after an opening parenthesis."""
READS = ()


def step(carry, prefix, upstream):
    # Do not carry a signal across packed-document boundaries.
    if prefix.position == 0 or prefix.document_ids[-1] != prefix.document_ids[-2]:
        return None, 0.0

    previous = prefix.token_strings[-2].rstrip()
    if previous.endswith('('):
        return None, 0.75
    return None, 0.0

programs.sol:
"""Lexical assignment/allocation detector, with weaker association cues.

Responses are negative and strongest on forms of 'assign'. Related words
about allocation, attribution, association, contribution and belonging are
weaker. Chinese/Japanese assignment words and the fragments ass/aff/conf
are also cues. 'Randomly' strengthens the next assignment/allocation word.
A following connector or grammatical ending gets a smaller response;
split/divide followed by into is recognized separately.
These are surface-text rules, not a semantic interpretation of each use.
"""
READS = ()

ASSIGN = {
    'assign': -6.1, 'assigns': -5.6, 'assigned': -4.8,
    'assigning': -5.5, 'assignment': -4.4,
    'assignments': -4.5, 'assignable': -2.7,
}
ALLOCATE = {
    'alloc': -2.4, 'allocate': -2.4, 'allocated': -2.1,
    'allocating': -2.2, 'allocation': -2.2,
    'allocations': -2.0, 'allocator': -1.0,
}
# Dispatch, bestow, allocate, arrange, configure and combine.
CJK_ASSIGNMENT = {
    '派': -2.65, '賦': -2.8, '赋': -3.5, '配': -1.3,
    '分配': -4.0, '安排': -2.0, '赋予': -2.1,
    '配置': -0.45, '搭配': -0.7,
}
CONNECTORS = {
    'to': .20, 'of': .68, 'a': .28, 'an': .14, 'the': .13,
    'each': .09, 'them': .14, 'it': .18, 'you': .06, 'for': .07,
}
ENDINGS = {
    'ing': .65, 'ment': .65, 'ments': .60, 's': .50, 'ed': .50,
    'ee': .38, 'ees': .30, 'able': .54,
    'ated': .48, 'ations': .37, 'ates': .64,
}


def lexical(raw):
    word = raw.strip().lstrip('_.(-')
    w = word.lower()
    spaced = raw[:1].isspace()
    if w in ASSIGN:
        value = ASSIGN[w]
        if w == 'assign' and not spaced:
            value = -4.4 if raw.startswith('_') else -5.8
            if raw.startswith('.'):
                value = -6.7
        if w.startswith('assignment') and not spaced and word == w:
            value += .7
        return value, 'assign'
    if w in ALLOCATE:
        return ALLOCATE[w], 'assign'
    if w.startswith('reassign') or w == 'asign':
        return (-2.7 if w == 'asign' else -4.1), 'assign'
    if w.startswith('associ'):
        value = -1.35 if w in ('associate', 'associates', 'associations') else -1.0
        if w == 'association' and word[:1].isupper():
            value = -.7
        if w in ('associated', 'association') and not spaced and word == w:
            value = -.65
        if w == 'associative':
            value = -.35
        return value, 'associate'
    if w.startswith(('attrib', 'atrib', 'setattribute', 'getattribute')):
        value = -.7
        if w in ('attrib', 'atrib'):
            value = -2.0
        if w.startswith('setattribute'):
            value = -1.3
        return value, 'attribute'
    if w.startswith('contrib'):
        if w in ('contrib', 'contribut', 'contributions'):
            return -.35, ''
        return (-.5 if w == 'contribution' else -.75), ''
    if w.startswith(('deleg', 'affiliat', 'allot', 'belong', 'attach')):
        return -.5, ''
    if w.startswith(('distribut', 'award')):
        return (-.1 if w.endswith('ed') else -.3), ''
    if w == 'homework':
        return -.55, ''
    if w in ('ass', 'aff', 'conf'):
        if w == 'ass' and raw.startswith('-'):
            return -.7, ''
        return (-.65 if w == 'conf' or word == 'ASS' else -.3), ''
    if w == 'appoint':
        return -.4, 'appoint'
    if w == 'partition':
        return -.3, 'partition'
    return CJK_ASSIGNMENT.get(word, 0.0), ''


def step(carry, prefix, upstream):
    doc, raw = prefix.document_ids[-1], prefix.token_strings[-1]
    value, family = lexical(raw)
