        _, previous_family, previous_value, previous_word = carry
        w = raw.strip().lower()
        if previous_family == 'assign':
            multiplier = CONNECTORS.get(w, 0.0) if raw.startswith(' ') else 0.0
            if raw.isalpha():
                multiplier = ENDINGS.get(w, 0.0)
            value += previous_value * multiplier
        elif previous_family == 'associate' and w in ('with', 'between', 'of'):
            value += previous_value * .17
        elif previous_family == 'attribute' and w == 'to':
            value += previous_value * .17
        elif previous_family in ('appoint', 'partition') and w == 'ing':
            value = -.4 if previous_family == 'appoint' else -.9
        if previous_word == 'randomly' and family == 'assign':
            value -= 1.1
        if previous_word in ('split', 'divide', 'divided') and w == 'into':
