FAMILIES = (
    (4.0, ('flight', 'flute')),
    (3.4, ('flying', 'flare', 'flaming', 'flutter', 'flown')),
    (0.6, ('flashlight', 'flashback', 'flagship')),
    (2.3, ('flag', 'flash', 'flux', 'flak', 'flav', 'flap', 'flask')),
    (1.7, ('flat', 'fluid', 'flower', 'flam', 'flip', 'fluct', 'fluor', 'flows')),
    (2.0, ('florida',)),
    (0.35, ('floor', 'flood', 'flesh', 'flock', 'flaw', 'flee', 'fled')),
)
ASSOCIATIONS = (
    (4.4, {'飞', '飛'}),
    (3.2, {'飞行', '飛行'}),
    (2.8, {'フラ', 'фл', '扁'}),
    (2.2, {'飞机', '飛機', '飛び', '飘', '漂', '流动', '流感', '旗帜'}),
    (1.0, {'平台', '浮', '旗', '闪', '航班', '火焰', '吹'}),
    (0.6, {'流', '风', '風', 'пл', '翼', 'wing', 'wings', 'feathers'}),
    (1.8, {'플'}),
    (0.4, {'花', '足球'}),
)


def response(raw):
    word = unicodedata.normalize('NFKC', raw).lstrip(' \t\r\n._-/([,:#')
    low = word.lower()
    if raw.strip() == 'ﬂ':
        return -3.8
    if low == 'fl':
        if word.isupper():
            return -4.5 if raw[:1].isspace() else -4.0
        if word[:1].isupper():
            return -5.1
        return -4.4 if raw == 'fl' else (-5.6 if raw[:1].isspace() else -5.2)
    if low in ('fla', 'fle', 'flo', 'flu', 'infl'):
        return {'fla': -3.2, 'fle': -2.2, 'flo': -1.4,
                'flu': -3.2, 'infl': -3.0}[low]
    if low in ('fi', 'ffi'):
        return -0.65
    if low in ('fly', 'flies', 'flew'):
        return -2.6 if raw[:1].isspace() else -1.9
    if low.startswith('fl'):
        for strength, stems in FAMILIES:
            if low.startswith(stems):
                return -strength
        return -1.15
    if low.startswith('confl'):
        return -0.65
    if low.startswith(('inflam', 'inflation', 'influenza')):
        return -1.1
    if low.startswith(('platform', 'football', 'aircraft', 'airplane')):
        return -1.05
    if low in ('plane', 'planes'):
        return -1.05
    for strength, words in ASSOCIATIONS:
        if low in words:
            return -strength
    return 0.0


def step(carry, prefix, upstream):
    raw = prefix.token_strings[-1]
    doc = int(prefix.document_ids[-1])
    base = response(raw)
    value = base
    if carry is not None and carry[0] == doc and raw[:1].isascii():
        if raw[:1].isalpha():
            value += carry[1]
    low = raw.lstrip(' \t\r\n._-/([,:#').lower()
    echo = 0.0
    if low.startswith('fl') and raw[-1:].isascii() and raw[-1:].isalpha():
        echo = base * (0.15 if low == 'fl' else 0.07)
    return (doc, echo), value

