"""Approximate two prominent responses of this component.

English: a negative activation on infinitival 'to' after ability or
permission language, including 'allow [object] to'. It also responds on
personal objects of enabling verbs. The object can intervene for a few
tokens; the estimate fades with distance and stops at the infinitive.

Spelling: some byte-fragment tokens completing katakana have large,
syllable-specific responses. The short groups below approximate those
responses. The initial chat-start marker has a fixed negative baseline.
Most other, smaller lexical variation is left at zero.
"""
READS = ()

ALLOW = {'allow', 'allows', 'allowing'}
ENABLE = {'enable', 'enables', 'enabling', 'enabled'}
PERMIT = {'permit', 'permits', 'permitted', 'permitting'}
PERSONAL = {'you', 'us', 'them', 'me', 'him', 'her', 'it'}

# Base response to 'to' with an intervening noun, and with no object.
STRENGTH = {'allow': (0.78, 1.02), 'enable': (0.57, 0.34),
            'permit': (0.36, 0.46), 'allowed': (0.35, 0.69)}

# Compact spelling-specific estimates, only for split character endings.
KANA = (('マメブベボ', 1.62), ('バミモホポチワ', 0.84),
        ('リニヌ', -1.35), ('レネノ', -0.84),
        ('テデツギジユ', -0.62), ('オゴヨダド', -0.28),
        ('キクケコパプ', 0.38))


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    reset = carry is None or carry[0] != doc
    if reset:
        carry = (doc, '', '', 99)
    _, previous_token, cue, distance = carry
    previous = previous_token.strip().lower()
    token = prefix.token_strings[-1]
    word = token.strip().lower()
    value = -0.2124 if reset and token == '<|im_start|>' else 0.0

    if token == ' to':
        if previous in {'ability', 'allowed'}:
            value = -0.72 if previous_token.startswith(' ') else -0.05
        elif previous in {'inability', 'capability', 'permitted'}:
            value = -0.33 if previous == 'inability' else -0.47
        elif previous in {'abilities', 'capabilities', 'capacity', 'unable'}:
            value = -0.12
        elif cue and distance <= 8:
            base, direct = STRENGTH[cue]
            if distance == 1:
                base = direct
            elif distance == 2 and previous in PERSONAL:
                base += 0.22 if previous in {'you', 'us'} else 0.11
            value = -base * 0.68 ** max(0, distance - 2)
        elif previous == 'able' and previous_token.startswith(' '):
            value = -0.21
        elif previous in {'ready', 'shown'}:
            value = -0.18
        cue = ''
    elif cue and distance == 1:
        if word in PERSONAL:
            if word in {'you', 'us'}:
                value = {'allow': -1.20, 'enable': -0.70,
                         'allowed': -0.70, 'permit': -0.40}[cue]
            else:
                value = -0.47 if cue == 'allow' else -0.27
        elif word in {'the', 'a', 'an', 'this', 'these'}:
            value = -0.30 if word == 'the' else -0.17
        elif word == 'for' and cue in {'allow', 'allowed'}:
            value = -0.48

    if not reset and '\ufffd' in token:
        last = prefix.text_prefixes[-1][-1:]
        for syllables, response in KANA:
            if last and last in syllables:
                value = response
                break

    if word in ALLOW:
        cue, distance = 'allow', 0
    elif word in ENABLE:
        cue, distance = 'enable', 0
    elif word in PERMIT:
        cue, distance = 'permit', 0
    elif word == 'allowed':
        cue, distance = 'allowed', 0
    elif any(c in token for c in '.!?;\n'):
        cue, distance = '', 99
    return (doc, token, cue, distance + 1), float(value)

