"""Predict the component's rare negative pulse in ability/permission phrases:
'at ability to', 'allow X to', and an object pronoun after allow/enable/permit."""
import re

READS = ()

ABILITY = re.compile(r"\bability\s*$")
PERMISSION = re.compile(
    r"\b(?:allow(?:s|ed|ing)?|enable(?:s|d|ing)?|permit(?:s|ted|ting)?)"
    r"(?:\s+\w+){0,4}\s*$"
)
DIRECT_PERMISSION = re.compile(
    r"\b(?:allow(?:s|ed|ing)?|enable(?:s|d|ing)?|permit(?:s|ted|ting)?)\s*$"
)
OBJECTS = {"you", "us", "them"}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    before = "" if carry is None or carry[0] != doc else carry[1]
    before = before.lower().rstrip()
    token_text = prefix.token_strings[-1]
    token = token_text.strip().lower()
    next_carry = (doc, (before + token_text)[-160:])

    if token == "to":
        if ABILITY.search(before):
            return next_carry, -0.70
        if PERMISSION.search(before):
            return next_carry, -0.65
    if token == "for" and DIRECT_PERMISSION.search(before):
        return next_carry, -0.50
    if token in OBJECTS and DIRECT_PERMISSION.search(before):
        return next_carry, -0.65

    return next_carry, 0.0

