"""Detect five, its number-word relatives, and associated calendar names.

Recognize ordinary, fullwidth, raised and lowered fives; English number
words; a few foreign five words/stems; and the Chinese numeral. May and
Friday respond more weakly, even when 'may' is an auxiliary verb.
The digit's response declines slightly with document position and changes
with the preceding token's character class. Indentation has an incidental
hump around 15 spaces or three tabs, and long space runs are negative.
Other tokens are assigned zero; small token-specific activity is omitted.
"""
import math

READS = ()
FIVE_WORDS = {
    'cinco': 1.69,
    'fünf': 1.53,
    'fün': 1.61,
    'пят': 2.22,
}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    pos = carry[1] + 1 if carry is not None and carry[0] == doc else 0
    text = prefix.token_strings[-1]
    word = text.strip().lstrip('-')
    lower = word.lower()
    previous = prefix.token_strings[-2] if pos else ''
    leading = text[:1].isspace()
    value = 0.0

    if text == '5':
        if pos == 0:
            value = 1.945
        else:
            value = 1.65 - 0.04 * math.log1p(pos)
            value += 0.07 * previous.isdigit()
            value -= 0.05 * previous.isspace()
            value += 0.11 * previous.endswith('.')
            value -= 0.25 * previous.endswith('=')
            value += 0.15 * previous.lstrip().isalpha()
            value -= 0.06 * previous.endswith(',')
    elif text == '５':
        value = 1.23
    elif '\ufffd' in text and prefix.text_prefixes[-1][-1:] in {'⁵', '₅'}:
        value = 2.34
    elif lower == 'five':
        value = 1.65 if leading else 1.40
        if word == 'Five':
            value = 2.05 if leading else 1.55
    elif lower in {'fifth', 'fifty'}:
        value = 1.35
    elif lower == 'fifteen':
        value = 0.82
    elif lower in FIVE_WORDS:
        value = FIVE_WORDS[lower]
    elif '五' in text:
        value = 2.48 if word == '五' else 1.50
    elif lower == 'may':
        value = 0.89 if word == 'May' else 0.52
        if not leading:
            value -= 0.12
    elif lower in {'friday', 'fridays', 'fri'}:
        value = 0.87 if word == 'Friday' else 0.55
        if lower == 'fridays':
            value = 0.74
        elif lower == 'fri':
            value = 0.52 if word == 'Fri' else 0.11
    elif text.isspace():
        horizontal = text.rstrip('\r\n')
        if horizontal and set(horizontal) <= {' ', '\t'}:
            tabs = horizontal.count('\t')
            spaces = horizontal.count(' ')
            if tabs and not spaces:
                value = 0.50 * math.exp(-((tabs - 3) / 0.8) ** 2)
            else:
                width = spaces + 4 * tabs
                value = 0.39 * math.exp(-((width - 15) / 2.3) ** 2)
                value -= 0.23 * math.exp(-((width - 31) / 7) ** 2)
    return (doc, pos), value

