"""Digit-five detector (layer 0 MLP, down_proj component 5331).

What it does: this component writes a strong "the current token means the number five"
signal into the residual stream. It is almost entirely a token-identity feature, and it
reads only the token at the current position (no context needed):

- the digit 5 itself, in any position ("15", "$5", "5th", "version 5"): about 1.5;
- the fullwidth digit ５ and the Chinese numerals 五 and 伍: about 1.5 (or more);
- the English words "five", "Five", "fifth", "fifteen", "Fifty": about 1.6;
- weaker, related month/day words: "May", "may", "Friday", "Fri" about 0.6;
- everything else: about 0.

The program is a set lookup on the current token. It is a readable stand-in for the
component: the table of small offsets for other tokens (about 9% of the variance spread
across thousands of tokens) is left out.
"""

READS = ()

FIVE_DIGITS = {"5", "５", "五", "伍"}
FIVE_WORDS = {"five", "fifth", "fifty", "fifteen"}
MAY_FRIDAY = {"may", "fri", "friday"}

FIVE_LEVEL = 1.5
WORD_LEVEL = 1.6
MAY_LEVEL = 0.6


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    word = token.strip().lower()
    if token.strip() in FIVE_DIGITS:
        value = FIVE_LEVEL
    elif word in FIVE_WORDS:
        value = WORD_LEVEL
    elif word in MAY_FRIDAY:
        value = MAY_LEVEL
    else:
        value = 0.0
    return carry, float(value)

