programs.sol:
"""Approximate a left-delimiter feature, not a general punctuation feature.

Most opening square, curly, and angle brackets have negative activations;
parentheses alone do not. Token fusion, completed pairs, newlines, and
LaTeX/HTML spellings modify the response. Local syntax heuristics distinguish
negative type/markup openings from positive comparisons using <, with a few
operator cases. Document-initial openings use weaker/different baselines.
Vertical bars get a small negative response; ordinary words predict zero.
Only 150 recent characters and document position are carried, resetting at
new documents. This captures the large delimiter responses, not all lexical
or contextual variation in the component.
"""
import re

READS: tuple[str, ...] = ()
PROSE_WORDS = {
    'the', 'and', 'for', 'in', 'as', 'or', 'to', 'of',
    'see', 'run', 'add', 'with', 'from', 'by', 'on',
}
FRACTIONS = {'frac', 'dfrac', 'tfrac', 'sqrt'}


def angle(s, tail, position, word):
    head, rest = s.split('<', 1)
    if rest.startswith('='):
        return 0.24
    if rest.startswith('<'):
        # A line-leading chained C++ stream insertion is not a comparison.
        if not s.startswith(' ') and not tail.rsplit('\n', 1)[-1].strip():
            return -0.8
        return 0.05 if s.startswith(' ') else 0.5
    if rest.startswith('/'):
        return 0.0 if '>' in rest else (-0.25 if not head else -0.4)
    if '>' in rest or rest.startswith(('-', '?')):
        return 0.0
    if head.strip():
        if '\\' in head:
            return -0.65
        if head.endswith('['):
            return -3.1
        if head.endswith('::') or '`' in head:
            return -2.2
        return -1.0
    if re.search(r'\b(?:struct|class)\s+\w+$', tail):
        return -3.0  # Generic type declarations and specializations.
    last = tail.rstrip()[-1:]
    if rest and not rest.isspace():
        if (len(rest) == 1 and rest.isalpha()
                and (last.isdigit() or len(word) == 1)):
            return 0.8
        return -2.0 if len(rest) == 1 and rest.isupper() else -1.7
    if '\n' in s:
        return -0.7
    if position == 0:
        return 2.4 if s.startswith(' ') else 1.0
    line = tail.rsplit('\n', 1)[-1]
    if line.lstrip().startswith('///'):
        return -3.1  # XML elements inside documentation comments.
    if not line.strip():
        return -2.8
    if re.fullmatch(r'\s*\d+\t\s*', line):
        return -1.7  # An indented, numbered code listing.
    if word == 'template':
        return -3.1
    if re.search(r'#\s*include\b', line):
        return -2.1
    if len(word) > 1 and word[0].isupper() and not word.isupper():
        return -1.65  # A capitalized type name before its parameters.
    if re.search(r'<[/!?]?[A-Za-z][\w:-]*(?:>|\s+[\w:-]+\s*=)', tail):
        return -2.8 if not word else -1.5
    comparison = bool(re.search(
        r'(?<!\w)(?:[a-z]\w{0,2}|[A-Z]|\d+)\s*<(?![|/!?=-])\s*[-\w(]',
        tail))
    if last.isdigit():
        return 1.3
    if (word and (len(word) == 1 or word[0].islower())
            and len(word) <= 3 and word not in PROSE_WORDS
            and not tail.rstrip().endswith("'" + word)):
        return 1.65 if comparison else 1.1
    if last in (')', ']', '|'):
        return 0.8
    if re.search(r'\\(?:delta|theta|epsilon|mu|alpha|beta|gamma)$', tail.rstrip()):
        return 1.2
    if re.search(r'\b(?:if|while|for)\s*\(', line):
        return 0.35
    return 0.5 if comparison and word not in PROSE_WORDS else -1.15


def response(s, tail, position):
    text = s.strip()
    before = tail.rstrip()
    match = re.search(r'(\w+)$', before)
    word = match[1] if match else ''
    if text in {'langle', 'lbrace', 'lbrack', 'Vert', 'vert', 'begin'}:
        if before.endswith('\\'):
            return -3.3 if text == 'langle' else -0.7
    if text == '&lt' or '＜' in text:
        return -0.9
    if text == 'lt' and before.endswith('&'):
        return -0.65
    if s.startswith(';') and before.endswith('&lt'):
        return -1.3
    if text == '|':
        return -0.3
    if any(c in text for c in '⟨〈《［【〔〖〘〚'):
        if '⟨' in text or '〈' in text:
            return -3.0
        return -0.5 if '《' in text else -1.1
    if '<' in s and not s.startswith('<|'):
        return angle(s, tail, position, word)
    if '[' in s:
        head, rest = s.split('[', 1)
        if ']' in rest:
            return 0.12 if rest.startswith(']') else 0.0
        if ']' in head:
            return -0.12
        if rest.startswith(('[', '{')):
            return -1.7
        if rest and rest[0].isalpha():
            return -1.4 if rest[0].isupper() and len(rest) > 1 else -0.4
        if not rest or rest.isspace():
            if position == 0:
                return -0.8
            if '\n' in s:
                return -0.72
            if head:
                if head.endswith((')', '}')):
                    return -0.5
                return -0.59 if '(' in head else -1.18
            return -0.7 if before[-1:].isalnum() and not tail.endswith('\n') else -1.1
        if rest.startswith(('"', "'")):
            return -0.69 if s.startswith(' ') else -0.23
        return -0.75 if s.startswith(' ') else -0.6
    if '{' in s:
        head, rest = s.split('{', 1)
        if '}' in rest:
            return 0.12 if rest.startswith('}') else 0.0
        if '\n' in s or '}' in head:
            return 0.0
        if head.endswith(('_', '^')):
            return -0.54 if head.endswith('_') else (-0.42 if not rest else -0.27)
        if rest.startswith(('"', "'")):
            return -0.52 if s.startswith(' ') else 0.05
        if rest.startswith('{'):
            return -1.2
        if not rest:
            if position == 0 and not head.strip():
                return -0.3 if head else 0.0
            if head.endswith((')', ']')):
                return -0.08
            if word == 'begin':
                return -1.7
            if word in FRACTIONS:
                return -0.03
            if before.endswith(')') or word in {'import', 'type'}:
                return -0.2
            if head.strip() and head.strip() != '(':
                return -0.8
            return -0.35 if not head and len(word) > 2 else -0.6
        return -0.55
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, '', 0)
    _, tail, position = carry
    s = prefix.token_strings[-1]
    value = response(s, tail, position)
    return (doc, (tail + s)[-150:], position + 1), float(value)

programs.luna:
"""Estimate a sparse response to opening punctuation in structured text.

Square and CJK opening brackets, braces, math subscripts, and vertical bars
get negative estimates. A less-than sign after a one-character alphanumeric
is treated as a comparison. The estimates are conservatively shrunk.
"""
READS = ()


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1].lstrip()
    previous = ""
    if len(prefix) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]:
        previous = prefix.token_strings[-2].strip()

    if token.startswith(("[", "《", "【")):
        value = -1.0
    elif token.startswith("_{"):
        value = -0.55
    elif token.startswith("{"):
        value = -0.4
    elif token.startswith("<") and not token.startswith(("</", "<=", "<|")):
        if len(previous) == 1 and previous.isalnum():
            value = 1.1
        else:
            value = -1.0
    elif token.startswith("|"):
