    else:
        value = 0.0
    return None, float(0.76 * value)

programs.sol:
"""Approximate the response to o-ending words and syllables.

Negative responses grow when an o-ending fragment continues a longer word,
and when earlier function words suggest Italian, Spanish, or Portuguese.
Short whole words and capitalized fragments are weaker.
Tokens ending in os or Cyrillic о receive smaller negative responses.
Other alphabetic tokens get a small language-dependent correction.
Counts fade by 1% per token and reset, along with the word, at documents.
This deliberately leaves individual-word exceptions unexplained.
"""
READS = ()

ROMANCE_WORDS = set(
    'di che per del della delle gli nel non è si al dei alla sono da '
    'anche più lo suo questo el los las y por para con es se su como '
    'más pero este esta sus sobre entre o os dos das em um uma com '
    'não na ao é foi são seu sua mas pelo pela'.split()
)
ITALIAN_WORDS = set(
    'di che della delle gli nel non è dei alla sono anche più suo questo'.split()
)
ENGLISH_WORDS = set(
    'the of and to is that it for on with be are was by an or at from '
    'this but not have has you we they their can will if there which '
    'one he she my us am come'.split()
)


def o_response(word, token, continued, romance, italian):
    if len(word) <= 4:
        if continued:
            return -0.26 if romance <= 0.61 else -1.16
        if len(word) <= 2:
            return -0.75 if italian > 0.43 else 0.0
        return -0.03 if romance <= 0.46 else -0.65
    if romance <= 0.30:
        if not continued:
            return -0.12
        return -0.15 if token[0].isupper() else -0.48
    if len(token) >= 4:
        return -0.96
    return -0.92 if romance <= 0.59 else -1.42


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        counts, tail = (0.0, 0.0, 0.0), ''
    else:
        counts, tail = carry[1], carry[2]
    s = prefix.token_strings[-1]
    token = s.strip()
    lower = token.lower()
    fragment = token.isalpha() and not s[:1].isspace()
    continued = bool(tail) and not s[:1].isspace()
    romance = counts[0] / (counts[0] + counts[2] + 2.0)
    italian = counts[1] / (counts[1] + counts[2] + 2.0)
    value = 0.0

    if token.isalpha():
        if lower.endswith('o'):
            word = (tail + token) if continued else token
            value = o_response(word, token, continued, romance, italian)
        elif lower.endswith('os'):
            value = -0.03 if romance <= 0.46 else (-0.58 if fragment else -0.29)
        elif lower.endswith('о'):
            value = -0.12 if fragment else -0.01
        elif lower.endswith('a'):
            value = 0.01 - 0.06*romance
        elif lower.endswith('e'):
            value = -0.001 - 0.035*romance + 0.077*italian
        elif lower[-1] not in 'aeiouо':
            value = 0.028*romance + 0.135*italian
        else:
            value = 0.006 - 0.031*romance + 0.003*italian

    lexicons = (ROMANCE_WORDS, ITALIAN_WORDS, ENGLISH_WORDS)
    counts = tuple(0.99*n + float(s.startswith(' ') and lower in words)
                   for n, words in zip(counts, lexicons))
    if s.isalpha():
        tail = (tail + s)[-40:]
    else:
        i = len(s)
        while i and s[i-1].isalpha():
            i -= 1
        tail = s[i:][-40:]
    return (doc, counts, tail), float(value)

