GENITIVE = {"'s", "’s"}
PEOPLE = {"husband", "wife", "son", "daughter", "brother", "sister", "father", "mother", "mom",
          "dad", "kids", "children", "child", "parents", "friends", "friend", "family", "students",
          "customers", "clients", "partner", "guests", "lady", "pet", "peers", "neighbors"}
OUTPUT = {"work", "works", "answer", "answers", "analysis", "analyses", "study", "knowledge",
          "reasoning", "conclusions", "research", "approach", "solution", "thinking", "understanding",
          "opinion", "experience", "data", "findings", "results", "responses", "calculations",
          "efforts", "thoughts", "plans", "first", "second", "next", "new", "last", "latest"}
ROLE = {"name", "task", "job", "position", "place", "role", "responsibility", "right", "rights",
        "fault", "part", "problem", "case", "kind", "future", "contact", "property", "thing",
        "back", "own", "respective", "former", "whole", "entire", "personal", "information",
        "side", "home", "life", "business", "team", "best", "time", "hand", "age", "current"}

def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    prev = prefix.token_strings[-2].strip().lower() if len(prefix.token_ids) > 1 else ""
    same_doc = len(prefix.token_ids) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]
    if not same_doc or not (prev in POSS or prev in GENITIVE):
        return carry, 0.0
    if word in PEOPLE or word in OUTPUT:
