STATEMENTS = {'return', 'catch', 'func', 'assert', 'sizeof', 'typeof'}
MATH_FUNCTIONS = {
    'sqrt', 'sin', 'cos', 'tan', 'ln', 'log', 'exp', 'floor', 'ceil',
    'gcd', 'left', 'right',
}
CONNECTIVES = {
    'and', 'or', 'but', 'as', 'in', 'on', 'at', 'by', 'of', 'to', 'from',
    'with', 'without', 'is', 'are', 'was', 'were', 'be', 'been',
