    if not previous:
        return 0.89 if spaced else 0.62
    if word.lower() in CONTROL:
        return 1.23 if spaced else 1.04
    if word.lower() in STATEMENTS:
        return 0.83 if spaced else 0.67
    if word.lower() == 'copyright':
        return 1.55
    if word.lower() in MATH_FUNCTIONS:
        return 0.25
    if word.lower() in CONNECTIVES:
        return 0.43
    if not word:
        return 0.50 if spaced else 0.28
    if word.isdecimal():
        return 0.03 if spaced else 0.10
    if len(word) == 1 and word.isascii() and word.isalpha():
        return 0.17
    if word.isalpha():
        if word[0].isupper():
            return 0.33 if spaced else 0.48
        if not spaced:
            return 0.47
        return 0.17 if previous[0].isspace() else 0.26
    if word.endswith(':') or word in {'=', '+', '-', '*', '/', '&&', '||'}:
        return 0.62
    if word[-1] in ')]}）】\'"”’':
        return 0.14
