    elif ')' in text or '）' in text:
        value = 0.0
    elif any(c.isalnum() for c in text):
        value = 0.0
        if text.startswith('('):
            value = -0.06 + 0.18 * (base - 0.3)
    elif text.count('(') >= 2:
        value = 1.1 + 0.35 * (base - 0.3)
        if any(c in text for c in '\'"'):
            value -= 0.4
    elif text.startswith('('):
        after = text[1:]
        following_bracket = {'[': 0.6, '{': 0.48, '$': 0.26, '&': 0.12}
        value = following_bracket.get(after[:1], 0.02)
        if after.startswith(('"', "'", '“', '`')):
            value = 0.16
        elif after.startswith('!'):
            value = 0.10 + 0.78 * (base - 0.3)
        elif after.startswith('\\'):
            value = 0.035 if '"' in after else 0.4
