import re

READS = ()

KEYWORDS = {"if", "and", "or", "not", "return", "for", "while", "elif", "in", "is", "else"}
OPEN_PAREN_TOKENS = {"(", " (", "（", " （", "([", "({", " ([", " ({", "(\n", " (\\"}


def _previous_class(prev: str) -> float:
    """How strongly an open paren is expected, given the token just before it."""
    word = prev.strip()
    if prev == "":
        return 0.0
    if word in KEYWORDS:
        return 0.85
    if word.isdigit():
        return 0.02
    if re.fullmatch(r"[A-Za-z_][A-Za-z_0-9]*", word):
        return 0.3  # an identifier, handled per form in step
    if word[-1:] in (")", "]", "}", '"', "'"):
        return 0.15
    return 0.43  # operators, punctuation, whitespace, newlines


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    if token not in OPEN_PAREN_TOKENS:
        return None, 0.0
    if len(prefix) < 2 or prefix.document_ids[-2] != prefix.document_ids[-1]:
        return None, 0.0
    prev = prefix.token_strings[-2]
    value = _previous_class(prev)
    if value == 0.3:
        # a glued "foo(" is a function call (0.41); a spaced "foo (" is weaker (0.24)
        value = 0.41 if token == "(" else 0.24
    return None, float(value)

