"""Modifier participles after a determiner.

The component reads a participle or participial adjective that comes straight after
"the", "a", "this", "all of the", "from the", etc., so that it opens a noun phrase
("the given value", "the specified columns", "a required field", "the resulting mixture").
It is strongest for "given", "specified", "selected", "resulting", "required", "desired",
"proposed", "available" (scale 2.5 vs 1.0), weaker for other participles after "the"
or a preposition, and zero when the same word is a predicate ("was given", "is required"),
or follows a pronoun or auxiliary. Other words give 0.

The program is stateless: it reads the current word and the word before it, which is reset
at each document boundary.
"""

READS = ()

DETERMINERS = {"the", "a", "an", "this", "that", "these", "those", "its", "their", "his",
               "her", "our", "your", "my", "any", "each", "every", "all", "some", "no",
               "both", "such", "other"}
PREPOSITIONS = {"of", "for", "with", "from", "in", "on", "by", "to", "at", "into", "under",
                "within", "via", "among", "per"}
PREDICATE_WORDS = {"is", "are", "was", "were", "be", "been", "being", "am", "have", "has",
                   "had", "not", "he", "she", "it", "they", "we", "i", "you", "him", "her",
                   "them", "us", "me"}
# Strongest modifiers: the participles that most often head "the X noun" phrases
STRONG = {"given", "specified", "selected", "chosen", "resulting", "required", "desired",
          "proposed", "available", "reported", "collected", "intended", "necessary"}
# Irregular participles and participial adjectives that also open noun phrases
IRREGULAR = {"given", "known", "written", "chosen", "broken", "stolen", "taken", "driven",
             "held", "built", "withheld", "shown", "found", "made", "sent", "lost", "left",
             "kept", "spoken", "risen", "fallen", "hidden", "worn", "undefined", "remaining",
             "existing", "upcoming", "missing", "preceding", "foregoing", "surrounding",
             "corresponding", "underlying", "adjacent", "apparent", "nearby", "available",
             "necessary", "present", "possible"}


def is_participle(word):
    if word in IRREGULAR or word in STRONG:
        return True
    return (word.endswith("ed") and len(word) > 3) or (word.endswith("ing") and len(word) > 4)


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    same_doc = len(prefix.document_ids) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]
    before = prefix.token_strings[-2].strip().lower() if same_doc else ""
    if not is_participle(word):
        return carry, 0.0
    if before == "the":
        gate = 1.0
    elif before in DETERMINERS or before in PREPOSITIONS:
        gate = 0.5
    elif before in PREDICATE_WORDS:
        gate = 0.0
    else:
        gate = 0.2
    strength = 2.5 if word in STRONG else 1.0
    return carry, float(strength * gate)

