"""Approximate strong responses to KNOW/MAKE inflections and Japanese commas.

English word forms have fixed positive strengths, adjusted for case and
boundary marks. The ideographic comma has a strong response when kana
occurred in the preceding 20 tokens of this document, and a much weaker
response otherwise. Other tokens return zero: their smaller, mixed lexical
and contextual responses are not modeled. State resets between documents.
"""
from collections import deque

READS = ()
KNOW = {'know': 1.087, 'knows': 0.984, 'knew': 0.965,
        'known': 0.848, 'knowing': 1.170}
MAKE = {'make': 0.594, 'makes': 0.584, 'made': 0.535, 'making': 0.598}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, deque(maxlen=20))
    recent = carry[1]
    token = prefix.token_strings[-1]
    word = token.strip()
    lower = word.lstrip('.-(_').lower()
    if word.startswith('、'):
        value = 0.81 if any(recent) else 0.066
    elif lower in KNOW:
        value = KNOW[lower]
        if word.startswith('-'):
            value *= 0.64
        elif lower == 'known' and not token.startswith(' '):
            value *= 0.75
        if word[0].isupper():
            value *= 0.92
    elif lower in MAKE:
        value = MAKE[lower]
        if word.startswith('-'):
            value *= 0.45
        elif lower != 'making' and (word[0].isupper()
                                   or not token.startswith(' ')):
            value *= 0.76
        elif lower == 'making' and word.islower():
            if not token.startswith(' '):
                value *= 0.72
    else:
        value = 0.0
    recent.append(any('\u3040' <= ch <= '\u30ff' for ch in token))
    return carry, float(value)

