WEATHER = {"weather", "fog", "thunder", "skies"}
SKY = {"sky", "rain", "rains", "storm", "storms", "sunny", "snowy"}
CLOUD_SERVICES = {"aws", "azure", "kubernetes", "ubernetes"}


