    doc = prefix.document_ids[-1]
    same_doc = carry is not None and carry[0] == doc
    after_cloud = same_doc and carry[1]
    token = prefix.token_strings[-1]
    bare = token.strip()
    word = bare.lstrip("-_/.'\"`([{").lower()

    if bare in {"云", "雲"}:
        value = 8.1 if bare == "云" else 7.5
    elif "云" in bare or "雲" in bare:
        # Yunnan is a place name, not a cloud word.
        value = 0.5 if bare.startswith("云南") else 3.0
    elif bare == "霞":  # glowing clouds at sunrise/sunset
        value = 2.9
    elif word == "cloud":
        if bare.startswith("_"):
            value = 4.5
        elif "Cloud" in bare:
            value = 5.5 if token.startswith(" ") else 5.2
        elif token.startswith(" "):
            value = 5.5
        else:
            value = 5.9
    elif word == "clouds":
        value = 4.9
    elif word in {"cloudy", "icloud"}:
        value = 2.7
    elif bare in {"龙", "龍"}:  # dragon characters
        value = 1.35
    elif bare in {"雨", "雷", "虹"}:  # rain, thunder, rainbow
        value = 0.9
    elif bare in {"雾", "霧", "天气", "天氣", "天空"}:
        value = 0.6
    elif word == "yun":  # Chinese cloud name in Latin letters
        value = 1.4 if bare == "Yun" else 0.75
    elif bare in {"обла", "クラ"}:  # Russian / Japanese cloud roots
        value = 1.2
    elif bare == "클":  # Korean cloud root
        value = 0.6 if token.startswith(" ") else 0.25
    elif word == "rainy":
        value = 1.0
    elif word in WEATHER or word in CLOUD_SERVICES:
        value = 0.55
    elif word in SKY:
        value = 0.33
    else:
        value = 0.0
    split_cloud = same_doc and carry[2] and token in {"loud", "LOUD"}
    if split_cloud:  # e.g. C + LOUD, or the spelling Kloud
        value = 5.6 if token == "LOUD" else 3.4

