programs.sol:
"""Negative pulses on word fragments after an L-ending, especially 'al'.

Use the preceding token's spelling, not its identity. Latin 'al', Cyrillic
'ал', and Arabic alif-lam are strongest; other L endings are weaker.
The current fragment sets the pulse size through its initial letter,
capitalization, length, and familiar inflectional/derivational endings.
Ordinary word starts and punctuation mostly receive no pulse. This is an
approximation: many small native responses and context effects are omitted.
"""
import unicodedata

READS = ()
AGENT_OR_IDEOLOGY = {'ism', 'ist', 'ists', 'isms', 'ista', 'istas', 'iste', 'isme'}
ROMANCE_ABSTRACT = {'idad', 'idades', 'ite', 'ites', 'ita', 'itat', 'itats'}
IZE_VERBS = {'ize', 'ized', 'izes', 'izing', 'ise', 'ised', 'ising'}
IZATION_NOUNS = {'ization', 'izations', 'isation', 'isations'}
LATINATE_ENDINGS = {'in', 'ine', 'ina', 'ino', 'ini', 'inho', 'inha'}
LINK_WORDS = {'and', 'of', 'for', 'de', 'do'}
OTHER_FUNCTION_WORDS = {'or', 'in', 'by', 'to', 'is', 'the', 'that'}


def fold(text):
    return ''.join(c for c in unicodedata.normalize('NFD', text.lower())
                   if not unicodedata.combining(c))


def preceding_strength(text):
    p = fold(text).strip()
    short = len(p) <= 4
    if p.endswith('al'):
        if text.lower().strip() != p:
            return 0.40  # Accented preceding spellings are weaker cues.
        return 1.0 if short else 0.77
    if p.endswith('all'):
        return 0.49
    if p.endswith(('el', 'il', 'ol', 'ul')):
        return 0.20
    if p.endswith('ll'):
        return 0.23 if short else 0.18
    if p.endswith('l'):
        return 0.18 if short else 0.13
    if p.endswith('ал'):
        return 0.74 if short else 0.32
    if p == 'л' and text[:1].isspace():
        return 0.47
    if p.endswith('аль'):
        return 0.43
    if p.endswith(('ел', 'ил', 'ол', 'ул', 'л')):
        return 0.22 if short else 0.08
    if p.endswith(('ال', 'آل')):
        return 0.57 if short else 0.06
    if p.endswith('ل'):
        return 0.30 if short else 0.12
    if p.endswith(('lar', 'лар')):
        return 0.38
    if p.endswith(('ль', 'ли')):
        return 0.15 if short else 0.23
    return 0.0


def fragment_strength(token):
    c = fold(token)
    if not c:
        return 0.0
    if token[0].isspace():
        word = c.strip()
        if word in LINK_WORDS:
            return 0.22
        return 0.09 if word in OTHER_FUNCTION_WORDS else 0.0
    if token[0] in '-`':
        return 0.31
    if not token[0].isalpha():
        return 0.0
    pulse = 0.84
    if c[0] in 'aeiouy':
        pulse += 0.10
    pulse += {'i': 0.28, 'u': 0.10, 'a': -0.49, 'd': 0.67}.get(c[0], 0.0)
    if token[0].isupper():
        pulse -= 0.43
    if len(token) == 1:
        pulse += 0.19
    if len(token) >= 6:
        pulse -= 0.42
    if c == 'is':
        pulse += 1.52
    elif c == 'um':
        pulse += 0.84
    elif c in AGENT_OR_IDEOLOGY:
        pulse += 0.43
    elif c in ROMANCE_ABSTRACT:
        pulse += 0.69
    elif c in IZE_VERBS:
        pulse -= 0.45
    elif c in IZATION_NOUNS or c in {'ity', 'ities'}:
        pulse -= 0.28
    elif c in LATINATE_ENDINGS:
        pulse += 0.54
    return max(0.0, pulse)


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    previous = 0.0 if carry is None or carry[0] != document else carry[1]
    token = prefix.token_strings[-1]
    value = -0.001 - previous * fragment_strength(token)
    return (document, preceding_strength(token)), float(value)

"""Estimate a zero-continuation response and a repeated-nine response.

For a zero, the two previous tokens supply digit-specific strengths: the
immediate digit matters most, especially nonzero even digits. Hex-letter
fragments also produce a positive response. Single Unicode decimal digits
are normalized to ASCII. Prefixes containing only zeros or only nines use
fixed initial responses. All other tokens return zero; smaller nonnumeric
responses are deliberately left unexplained.
"""
import unicodedata

READS = ()

# A zero's response after each of the ten ordinary decimal digits.
ZERO_STRENGTH = dict(zip('0123456789',
    (0.27, 0.51, 0.96, 0.72, 1.00, 0.66, 1.11, 0.65, 0.92, 0.63)))


def decimal_digit(token):
    # Normalize single Unicode decimal digits to their ASCII equivalents.
    if len(token) == 1 and token.isdecimal():
        return str(unicodedata.decimal(token))
    return token


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous, before_previous, uniform = '', '', None
    if carry is not None and carry[0] == doc:
        previous, before_previous, uniform = carry[1:]
    token = decimal_digit(prefix.token_strings[-1])
    if carry is None or carry[0] != doc:
        uniform = token if token in ('0', '9') else None
    elif token != uniform:
        uniform = None
    value = 0.0
    if token == '0':
        value = ZERO_STRENGTH.get(previous, -0.07)
        if previous not in ZERO_STRENGTH:
            letters = previous.strip().lower()
            if letters and all(c in 'abcdef' for c in letters):
                value = 0.25
            elif (letters.startswith(('x', '\\x'))
                  and letters[-1:] in 'abcdef'):
                value = 0.55
        if before_previous in ZERO_STRENGTH:
            value += (0.02 if before_previous == '0' else
                      0.07 + 0.10 * ZERO_STRENGTH[before_previous])
    elif token == '9' and previous == '9':
        value = 0.66
    if uniform == '0':
        value = -0.12
    elif uniform == '9':
        value = 0.57
    return (doc, token, previous, uniform), value

