            if previous in {'the', 'many', 'several', 'one', 'two', 'three'}:
                value += 0.4 if plural else 0.5
            elif previous in {'a', 'an', 'some', 'few'}:
                value += 0.2
            elif previous in {'primary', 'api', 'secret'}:
                value -= 1.3 if not plural else 0.5
            elif previous and not any(c.isalnum() for c in previous):
