programs.sol:
"""Approximate bracket-onset pulses using shapes and familiar word classes.
Opening square brackets and their first contents usually get positive pulses.
Nearby openings weaken these; document-initial openings get negative values.
Closing brackets use their distance from the latest '['. Separate rules cover
Chinese 在 (except 'now'/'exist' words), 【, and attached angle-bracket names.
Other positions return zero; word-specific variation is not modelled.
"""
import math

READS = ()
LOG_LEVELS = {'INFO', 'WARN', 'WARNING', 'ERROR', 'DEBUG', 'TRACE', 'FATAL'}
ARTICLES = {'a', 'A', 'the', 'The'}
PRIMITIVE_TYPES = {'str', 'string', 'int', 'float', 'bool', 'bytes'}
TYPE_CONSTRUCTORS = {'List', 'Dict', 'Set', 'Tuple', 'Optional', 'Union'}
RUST_DIRECTIVES = {'warn', 'allow', 'deny', 'forbid', 'inline', 'doc'}


def value(s, previous, width):
    if not s:
        return 0.0
    if '[' in s:
        before, after = s.split('[', 1)
        if previous.endswith('[') and s.startswith('[@'):
            return -1.9
        if not previous:
            if after.startswith((']', '"', "'")):
                return -0.1
            if after.isalpha():
                return -0.5
            return -2.5 if not before else -1.8
        if before.endswith(']'):
            return 0.7
        if before.endswith('\\'):
            return 0.8
        pulse = 1.9 if not before else 1.75 if before.isspace() else 1.2
        if after.isalpha():
            pulse = 2.1 if len(after) == 1 else 2.4
        if after in PRIMITIVE_TYPES:
            pulse = 2.7
        if after in TYPE_CONSTRUCTORS:
            pulse = 1.9
        if '\n' in after or after.startswith(']'):
            pulse -= 0.5
        if width == 1:
            pulse -= 0.8 if after.isalpha() else 2.0
        else:
            pulse -= 0.4 * math.exp(-width / 25.0)
        return pulse
    if previous.endswith('[') and ']' not in s:
        if previous.endswith('\\['):
            return 0.7
        if previous.endswith(('#[', '#![')):
            return 4.8 if s in RUST_DIRECTIVES else 3.2
        if s.isdigit():
            return 1.67 if s == '0' else 1.28
        if s in LOG_LEVELS:
            return 3.5
        if s == 'email':  # [email protected] redaction marker.
            return 5.5
        if s in ARTICLES:
            return 2.7
        if s.startswith('^'):
            return 4.5
        if s.startswith('==='):
            return 3.9
        if s.isspace():
            return 2.17 if s == ' ' else 0.8
        if s[0].isspace():
            return 1.4
        pulse = 2.3 if len(s) == 1 else 1.6
        if 2 < len(s) <= 7 and s[0].islower():
            pulse = 1.8
        if any(c in previous for c in "(\"'`“"):
            pulse += 0.9
        return pulse
    if ']' in s:
        if width <= 3:
            return -0.4 if width == 2 else -0.2
        return 0.95 if width > 1000 else min(0.7, 0.23 * math.log(width) - 0.18)
    if '在' in s and not any(w in s for w in ('现在', '現在', '存在')):
        return 1.2 if s.startswith(('在', '，在')) else 0.9
    if '【' in s:
        return 1.2 if previous else -2.5
    if previous.endswith(('[\\', '[@', '[\n')):
        return 0.45 if previous.endswith('[\n') else 0.85
    if s.startswith('<') and len(s) > 1 and s[1].isalnum() and not s.endswith('>'):
        return 0.65
    return 0.0


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    previous, width = carry[1:] if carry and carry[0] == document else ('', 10000)
    s = prefix.token_strings[-1]
    prediction = value(s, previous, width)
    width = 1 if '[' in s else width + 1
    return (document, s, width), float(prediction)

