"""Recognize an opening square bracket and its first contents.

The strongest recurring responses occur at bracketed examples, citations,
and list entries. A few recurring Chinese tokens also produce a positive pulse.
"""

READS = ()


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    previous = prefix.token_strings[-2] if len(prefix) > 1 else ""
    same_document = len(prefix) > 1 and (
        prefix.document_ids[-1] == prefix.document_ids[-2]
    )

    if "[@" in token:
        return None, -2.0
    if "[" in token or (same_document and previous.rstrip().endswith("[")):
        return None, 1.8
    if "【" in token:
        return None, 1.2
    if "在" in token:
        return None, 1.1
    if "<" in token and ">" not in token:
        return None, 0.8
    return None, 0.0

