"""A small multilingual spelling detector.

The strongest negative responses belong to Ukrainian, Persian and Catalan
spellings.  Distinctive letters identify Ukrainian/Persian context; this lets
shared Slavic endings and Persian particles receive stronger responses without
treating Russian and Arabic the same way. A confirmed Catalan function word
also enables a short-lived Catalan mode:
shared particles, accented vowels and suffixes become more negative there.
Most other tokens stay near zero. This approximates the large language-linked
responses rather than the many smaller, idiosyncratic lexical responses.
"""
READS = ()

UKRAINIAN = frozenset('іїєґІЇЄҐ')
PERSIAN = frozenset('پچژگی')
CATALAN_CULTURE = {'Barcelona', 'Catalonia', 'Catalan', 'Catalunya'}
CATALAN_MARKERS = {'amb', 'els', 'aquest', 'aquesta', 'aquests', 'avui'}
CATALAN_PARTICLES = {'amb', 'els', 'dels', 'aquest', 'aquesta', 'aquests'}
# Slavic ending pieces; об also appears in the Ukrainian conjunction щоб.
UK_ENDINGS = {
    'ня', 'сь', 'тя', 'ого', 'ому', 'ний', 'них', 'ув', 'об',
}
UK_SHORT_ENDINGS = {
    'а', 'и', 'у', 'о', 'ь', 'й', 'к', 'е', 'х', 'ки', 'на', 'ку',
    'ля', 'но', 'я', 'сть', 'ться', 'ну',
}
PERSIAN_PREPOSITIONS = {'در', 'به', 'با', 'بر'}


def step(carry, prefix, upstream):
    s = prefix.token_strings[-1]
    word = s.strip()
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        uk = fa = ca = 0
        previous = ''
    else:
        _, uk, fa, ca, previous = carry
    uk = max(uk - 1, 0)
    fa = max(fa - 1, 0)
    ca = max(ca - 1, 0)
    # Confirm a whole word, rather than mistaking English "ambassador" or
    # Spanish "ambas" for the Catalan preposition "amb".
    if previous.startswith(' ') and previous.strip() in CATALAN_MARKERS:
        if not s or not s[0].isalpha():
            ca = 256
    if any(c in UKRAINIAN for c in s):
        uk = 64
    if any(c in PERSIAN for c in s):
        fa = 64

    value = -0.001
    if word in CATALAN_CULTURE:
        value = -1.9 if word == 'Barcelona' else -2.2
    elif word == 'Joan':
        value = -1.3
    elif (word in CATALAN_PARTICLES
          and (s.startswith(' ') or word == 'amb')):
        value = -1.1 if s.startswith(' ') else -0.4
    elif s in {'à', 'À', 'ò', 'ó', 'è', 'ès', 'ió'}:
        value = -0.45 if word in {'à', 'À'} else -0.27
    # Pieces of Catalan -eix-, -itzar, -ació and -ament endings.
    elif word in {'ix', 'itz', 'acio', 'ament'}:
        value = -0.38
    elif s == ' per':
        value = -0.2
    elif s == ' del':
        value = -0.16

    # Catalan background plus common grammatical words and suffix classes.
    if ca:
        if word.isalpha():
            value = min(value, -0.5)
        if word in {'amb', 'quest'}:
            value = -3.0
        elif s in {'à', 'À', 'ò', 'ó', 'ix', 'itz', 'ament', 'itat'}:
            value = -2.4
        # Plural, participial and nominal ending fragments.
        elif s in {'at', 'ats', 'ades', 'ions', 'ió', 'acio'}:
            value = -1.6
        elif word in {'per', 'els', 'les', 'és', 'tot', 'una'}:
            value = -1.9
        elif word in {'i', 'del', 'el', 'un', 'com', 'que', 'l', 'd', 'ser'}:
            value = -1.15
        elif word in {'de', 'la', 'va', 'no', 'ha'}:
            value = -0.7
        elif word in {'a', 'en', 'des', 'al'}:
            value = -0.4

    if word in {'і', 'ї'}:
        value = -0.85 if s.startswith(' ') else -1.1
    elif word == 'є':
        value = -0.52
    elif uk:
        if word in UK_ENDINGS and not s.startswith(' '):
            value = -1.0
        elif word in UK_SHORT_ENDINGS and not s.startswith(' '):
            value = -0.45
        elif s == ' з' or s == ' ц':
            value = -1.0
        elif s in {' у', ' до', ' за', ' я'}:
            value = -0.38
        elif word == 'ного':
            value = -0.7
        elif word.startswith('Укра'):
            value = -0.7
        elif word == '�':
            value = -0.35
        if word == 'а' and previous == ' т':
            value = -1.1

    if s.startswith(' ') and word in PERSIAN_PREPOSITIONS:
        value = -0.8 if word == 'به' else -0.55
    elif word == 'ه':
        value = -0.6 if fa else -0.3
    elif fa:
        if s == ' و':
            value = -0.55
        elif word in {'ده', 'شه', 'ها'}:
            value = -0.4

    return (doc, uk, fa, ca, s), float(value)

programs.luna:
"""A small Unicode-script heuristic for multilingual-looking text.

Non-Latin letters and accented Latin letters mark a token.  Keep the last
twenty marks so later tokens in the same passage can share that cue.
"""
import unicodedata

READS = ()


def _foreignness(text):
    score = 0.0
    for ch in text:
        if ch.isalpha():
            name = unicodedata.name(ch, "")
            if "LATIN" not in name:
                score = max(score, 1.0)
            elif ord(ch) > 127:
                score = max(score, 0.7)
    return score


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    history = () if carry is None or carry[0] != doc else carry[1]
    now = _foreignness(prefix.token_strings[-1])
    signal = max(now, 0.55 * max(history, default=0.0))
    history = (history + (now,))[-20:]
    return (doc, history), float(-0.013 * signal)

programs.sol:
"""A category-level approximation of initial-token and authority-language responses.

The high-causal-importance examples occur at model-visible row/document starts.
There, use positive defaults for word fragments and numbers, and negative
levels for recognized prose openings, code openings and heading marks. Keep
this mode for an opening run of identical tokens. Later, use small defaults,
with calibrated control markers and legal/administrative word classes; raise
the latter after a recent state- or law-related modifier. Track only two
recent token spellings and reset all state at each document boundary.

This intentionally omits most idiosyncratic low-amplitude lexical variation.
"""
READS = ()

AUTHORITY_TERMS = set('secretary director minister mayor officer officers '
                      'leader leaders '
                'leadership committee commission administration administrative '
                'authority executive elected approval grant legal provincial '
                'arrest decision decisions'.split())
LEGAL_TERMS = set('law laws legislation constitution constitutional treaty regulation '
          'regulations rule rules directive enforcement rights permission '
          'permissions'.split())
STATE_TERMS = set('government state senate council congress parliament ministry '
                 'president governor court department national'.split())
LEGAL_MODIFIERS = set('state federal central provincial law laws legal judicial '
                     'constitutional government court'.split())
DECLARATIONS = set('def class const public void export template'.split())
IMPORTS = {'import', 'package'}
CODE_OPENINGS = {'from', 'using', 'namespace', 'private', 'function', 'var', 'let'}

AUTHORITY_VOCABULARY = AUTHORITY_TERMS | LEGAL_TERMS | STATE_TERMS


def initial(s, word):
    if s.startswith('<|'):
        return 0.01
    if not word:
        if '\n' in s:
            return -0.17
        if '\t' in s:
            return -0.03
        return -0.22 if len(s) == 1 else -0.10
    bare = s == s.lstrip()
    if bare:
        if set(s) == {'#'}:
            headings = (-1.24, -0.96, -0.54, -0.19, -0.08, 0.02)
            return headings[min(len(s), 6) - 1]
        if s.startswith('#'):
            return -0.35
        if s in {'//', '/*', '/**', '<?'}:
            return -0.49
        if s in IMPORTS:
            return -0.83
        if s in DECLARATIONS:
            return -0.40
        if s in CODE_OPENINGS:
            return -0.17
        if s == 'The':
            return -0.64
        if s == 'This':
            return -0.55
        if s == 'Title':
            return -1.00
        if s in {'What', 'How'}:
            return -0.59
        if s in {'A', 'An', 'I', 'We', 'You', 'If', 'Let', 'Welcome', 'Why'}:
            return -0.25
        if s in {'It', 'These', 'There', 'When', 'Which', 'Who', 'Please'}:
            return -0.12
    if s == ' The':
        return 0.025
    if s == ' A':
        return 0.096
    if word == 'the':
        return -0.235 if bare else -0.102
    if word in {'a', 'an'}:
        return 0.07 if bare else 0.24
    if word in {'is', 'are', 'be'}:
        return 0.03 if bare else -0.08
    if word in AUTHORITY_VOCABULARY:
        return 0.66
    if word.isdecimal():
        if len(word) == 1 and word.isascii():
            return 0.15 if word in {'0', '1'} else 0.29
        return 0.15
    if all(not c.isalnum() for c in word):
        if word.startswith(('(', ')')):
            return 0.14
        if word == ',':
            return 0.135
        if word in {'-', '|'}:
            return -0.13 if bare else 0.02
        if word.startswith('.'):
            return -0.05
        if word.startswith(('"', "'", '“', '‘')):
            return 0.08
        return 0.02
    if any('\u4e00' <= c <= '\u9fff' for c in word):
        return 0.20
    if s.strip().isupper() and len(s.strip()) == 1:
        return 0.02 if bare else 0.10
    if not bare:
        return 0.22 if s.strip().istitle() else 0.17
    return 0.13


CONTROL_MARKERS = {
    "<think>": -0.138,
    "</tool_call>": 0.124,
    "<tool_response>": -0.088,
    "</tool_response>": 0.077,
    "<|endoftext|>": 0.029,
    "<|im_start|>": 0.027,
}


def background(s, word, recent):
    if word in AUTHORITY_VOCABULARY:
        if word in AUTHORITY_TERMS:
            value = -0.15
        elif word in STATE_TERMS:
            value = -0.056
        else:
            value = 0.021
        state_context = any(w in {'state', 'federal', 'central', 'provincial'}
                            for w in recent)
        legal_context = any(w in LEGAL_MODIFIERS for w in recent)
        if word in STATE_TERMS:
            value += 0.65 if state_context else 0.35 if legal_context else 0.0
        elif word in LEGAL_TERMS:
            value += 0.72 if state_context else 0.65 if legal_context else 0.0
        else:
            value += 0.40 if legal_context else 0.0
        return value
    if s in CONTROL_MARKERS:
        return CONTROL_MARKERS[s]
    if s == ' _':
        return -0.10
    if s.strip() == '__':
        return 0.031
    if s.strip() == '✓':
        return 0.10
    if s.strip() in {'—', '–'}:
        return 0.033
    if not word or all(not c.isalnum() for c in word):
        return 0.005
    return 0.001


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    s = prefix.token_strings[-1]
    token = prefix.token_ids[-1]
    word = s.strip().lower()
    first = carry is None or carry[0] != doc
    if first:
        position, recent = 0, ()
        initial_token, uniform = token, True
    else:
        _, position, recent, initial_token, uniform = carry
        position += 1
        uniform = uniform and token == initial_token
    if uniform:
        value = initial(s, word)
    else:
        value = background(s, word, recent)
        value += 0.025 if position == 1 else 0.016 if position == 2 else 0.0
    recent = (recent + (word,))[-2:]
    return (doc, position, recent, initial_token, uniform), float(value)

"""English phrase endings: strong comparison and boundary responses at 'to',
smaller attachment/infinitive responses, and negative ability/access responses.

The preceding word chooses a phrase family and its approximate strength.
A few analogous 'for', 'with' and membership phrases are included. This
captures the conspicuous collocations, not weaker lexical variation elsewhere.
State is a short text suffix, reset when the document changes.
"""
import re
READS = ()

COMPARISON = {'compare', 'compares', 'compared', 'comparing', 'comparison'}
STARTING = {'start', 'starts', 'started', 'starting',
            'begin', 'begins', 'began', 'beginning'}
PREPARING = {'prepare', 'prepares', 'prepared', 'preparing'}
ATTEMPT = {'try', 'tries', 'tried', 'attempt', 'attempts', 'attempting',
           'attempted', 'decide', 'decides', 'decided'}
RELATION = {'equal', 'similar', 'identical', 'equivalent', 'comparable',
            'relate', 'relates', 'related', 'relating', 'relation',
            'linked', 'link', 'connected', 'attached', 'coupled', 'subject'}
PROXIMITY = {'close', 'closer', 'adjacent', 'next', 'parallel', 'apart'}
INTENTION = {'plan', 'plans', 'planned', 'planning', 'aim', 'aims',
             'seek', 'trying', 'choose', 'managed', 'fail', 'failed',
             'continue', 'continues', 'continued', 'continuing'}
BOUNDARY = {'prior', 'limited', 'reduced', 'reduces', 'bound'}
DIRECTION = {'up', 'down', 'back', 'left', 'over', 'forward'}
GRATITUDE = {'grateful', 'thankful'}


def to_response(word):
    if word in COMPARISON:
        return 4.25 if word == 'compared' else 3.0
    if word == 'relative':
        return 2.1
    if word == 'up':
        return 1.8
    if word == 'equal' or word in BOUNDARY:
        return 1.45
    if word in {'similar', 'identical', 'equivalent', 'comparable', 'contrast', 'set'}:
        return 1.3
    if word in PREPARING:
        return 1.65
    if word in STARTING:
        return 1.35
    if word in ATTEMPT:
        return 1.15
    if word in RELATION | PROXIMITY | INTENTION:
        return 0.85
    if word in {'ready', 'sure', 'hard', 'difficult',
                'time', 'about', 'addition'}:
        return 1.0
    if word in {'change', 'changes', 'changed', 'switch', 'convert', 'converted'}:
        return 1.0
    if word in DIRECTION | {'like', 'not'}:
        return 0.7
    if word == 'able':
        return -1.18
    if word in {'access', 'going'}:
        return -1.0
    if word in {'ability', 'unable', 'entitled', 'entitlement',
                'permission', 'rights'}:
        return -0.6
    if word in GRATITUDE:
        return -1.7
    if word in {'important', 'essential'}:
        return -0.5
    if word in {'need', 'needed'}:
        return -0.15
    if word.isdigit():
        return 0.53
    return 0.15


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    before = '' if carry is None or carry[0] != doc else carry[1]
    value = 0.0
    if token in {' to', ' for', ' with', ' member', ' members'}:
        match = re.search(r'([A-Za-z]+|[0-9]+)[\s"\u201d]*$', before)
        word = match[1].lower() if match else ''
        if token == ' to':
            value = to_response(word)
        elif token == ' for':
            if word in PREPARING | {'preparation', 'check', 'checking'}:
                value = 1.0
            elif word in {'up', 'look', 'looking', 'search', 'searching', 'ready'}:
                value = 0.65
            elif word in GRATITUDE or before.lower().endswith('thank you'):
                value = -1.5 if word in GRATITUDE else -0.85
        elif token == ' with' and word in COMPARISON:
            value = 1.2 if word == 'compared' else 0.8
        elif token in {' member', ' members'}:
            value = -0.85 if word == 'family' else -0.2
    return (doc, (before + token)[-60:]), value

programs.haiku:
"""layers.0.mlp.down_proj:5353 -- a "to / for after a word" detector.

What it does: this component fires almost only on the word "to" (and a little on "for").
Its sign and size are set by the word just before it:
  * "compared to"                       -> strongly positive (~4)
  * "up to", "similar/equal/prior/relative/... to", "began/try/decided/prepare... to"
                                        -> positive (~1.4)
  * "related/close/back/down/next... to" -> mildly positive (~0.8)
  * "able/unable/ability/access/going/enough/important ... to"
                                        -> negative (~-0.9)
  * "went/come/free/attention ... to"  -> slightly negative
  * a number before "to" ("from 1 to 5") -> small positive
  * any other "to" -> small positive (0.1); "for" only after a few words.
Everything else predicts 0.

Why: in the decomposition this component reads the MLP hidden state at "to" and
writes a direction that depends on the lexical context of the preceding word; the
word lists below are the human-readable version of that lookup.
"""

READS = ()

COMPARED = ("compar",)
HIGH = ("try", "tri", "attempt", "begin", "began", "start", "started", "decid", "continu",
        "prepar", "reduc", "convert", "similar", "equal", "equiv", "comparable", "identical",
        "prior", "relative", "limited", "contrast", "addition", "bound", "opposed", "choose",
        "determin", "estimat", "predict", "updat", "change", "switch", "transition", "linked")
HIGH_WORDS = {"up", "time", "set", "near", "opposite", "contrary", "superior", "regard",
              "whether", "amount", "amounts", "seek", "add", "found", "tend", "wait"}
MID = ("relat", "close", "adjacent", "connect", "attach", "coupl", "subject", "parallel",
       "changes", "fail", "manag", "plan", "aim", "ready", "sure", "hard", "difficult")
MID_WORDS = {"back", "forward", "down", "not", "like", "next", "about", "left", "added"}
NEG = ("able", "unable", "abil", "access", "entitle", "permission", "important", "enough",
       "grateful", "rights", "obvious", "essential", "consent")
NEG_WORDS = {"going"}
MILD_NEG = {"went", "came", "go", "come", "free", "willing", "contribution", "attention",
            "sent", "answer", "proud"}
NEUTRAL = {"need", "needed", "needs", "way", "ways", "order", "how", "is", "used", "you",
           "them", "me", "us", "him", "as", "seems", "expected", "had"}


def value_to(prev):
    w = prev.lower()
    if w.startswith(COMPARED):
        return 4.0
    if w.startswith(HIGH) or w in HIGH_WORDS:
        return 1.4
    if w.startswith(MID) or w in MID_WORDS:
        return 0.8
    if w.startswith(NEG) or w in NEG_WORDS:
        return -0.9
    if w in MILD_NEG:
        return -0.3
    if w in NEUTRAL:
        return 0.0
    if prev.isdigit():
        return 0.5
    return 0.1


def value_for(prev):
    w = prev.lower()
    if w.startswith(("prepar", "check", "look", "ready")) or w == "up":
        return 0.8
    if w.startswith(("grateful", "award", "nominat", "famous", "renown")) or w == "responsibility":
        return -0.8
    return 0.0


def step(carry, prefix, upstream):
    if len(prefix.token_ids) < 2 or prefix.document_ids[-2] != prefix.document_ids[-1]:
        return None, 0.0
    cur = prefix.token_strings[-1].strip()
    prev = prefix.token_strings[-2].strip()
    if cur == "to":
        return None, value_to(prev)
    if cur == "for":
        return None, value_for(prev)
    return None, 0.0

