"""Large lexical responses to 'will', 'but/although', and aspect particles.

Chinese 'just', 'already', and 'not yet' are especially strong. Several
translations of 'but' and 'already' also respond. Case and initial space
matter. Two idioms, 'even/as though' and 'nothing/help but', are weaker
than ordinary concessions. Tool/thinking delimiters have small separate
responses. All unlisted tokens are predicted near zero.
"""
READS = ()

# Concessions and aspect: these are lexical cues, not a full word class.
CUES = {
    'but': 0.99, 'although': 0.87, 'though': 0.82,
    'shall': 0.16,
    'но': 0.61, 'pero': 0.55, 'mais': 0.42, 'aber': 0.29, 'zwar': 1.0,
    'already': 0.8, 'schon': 0.8, 'уже': 0.8, 'bereits': 0.95,
    'newly': 0.65, '刚': 2.7, '剛': 1.7, '刚刚': 2.0,
    '已': 0.85, '已经': 1.1, '已經': 1.0, '早已': 1.1,
    '未': 1.5, '还没有': 1.5, '尚未': 2.0, '还未': 2.0,
    '还没': 1.85, '還沒': 2.0, '虽然': 1.7, '雖然': 1.7,
    '虽': 2.5, '雖': 2.3,
    # Structured-message boundaries, a separate formatting response.
    '<tool_call>': 0.31, '</tool_call>': 0.39,
    '<tool_response>': 0.15, '</tool_response>': -0.12,
    '</think>': -0.21,
}
SPACED_WORDS = {'но', 'pero', 'mais', 'aber', 'zwar',
                'schon', 'уже', 'bereits'}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    prev = carry[1] if carry is not None and carry[0] == doc else ''
    raw = prefix.token_strings[-1]
    token = raw.strip()
    word = token.lower()
    spaced, capital = raw[:1].isspace(), token[:1].isupper()
    value = CUES.get(word, -0.001)
    if word in SPACED_WORDS:
        value *= 0.1 if not spaced and not capital else 0.65 if capital else 1
    if word == 'will':
        value = 0.78 if capital else 0.93 if spaced else 0.69
        if not capital and spaced and prev == 'you':
            value = 1.05
    elif word in {"'ll", '’ll'}:
        value = 0.70 if prev in {'i', 'it'} else 0.80
    elif word == 'but':
        if capital:
            value = 0.74 if spaced else 0.61
        elif not spaced:
            value = 0.90
        if prev in {'nothing', 'help'}:
            value = 0.43 if prev == 'nothing' else 0.55
    elif word == 'although' and capital:
        value = 0.80 if spaced else 0.70
    elif word == 'though':
        if capital:
            value = 0.77 if spaced else 0.70
        if prev in {'even', 'as'}:
            value = 0.23 if prev == 'even' else 0.14
    elif word == 'already':
        if capital:
            value = 1.0
        elif prev in {'have', 'has', 'had', "'ve", '’ve', 'not'}:
            value = 0.51 if prev == 'not' else 0.69
        elif prev in {'was', 'were'}:
            value = 1.04
    return (doc, word), float(value)

