programs.sol:
"""Approximate a negative response to case-mixed identifier fragments.

LowerCamelCase is strong, especially getter/setter, predicate, event-handler
and 'to...' prefixes. PascalCase is weaker. Long or acronym tails weaken the
lowercase-starting response; very short mixed-case fragments stay strong.
The i-/e- and Mc-/Mac- naming prefixes also weaken the response. A few
scientific abbreviations, tool tags and README are calibrated separately.
Only the current token is read: these are spelling rules, not a code parser.
"""
import re

READS = ()
CAMEL_WORD = re.compile(r'[A-Za-z]*[a-z][A-Z][A-Za-z]*')
PARTS = re.compile(r'[A-Z]?[a-z]+|[A-Z]+')
# Extra response for lowerCamelCase / PascalCase operation prefixes.
OPERATIONS = {
    'get': (-2.4, -1.5),
    'set': (-1.6, -1.2),
    'on': (-1.3, -0.4),
    'to': (-1.4, -1.2),
}
PREDICATES = {'is', 'has', 'can', 'should'}
MUTATIONS = {'add', 'remove', 'delete', 'create', 'update', 'insert'}
SHORT_UNITS = {'kB': -4.9, 'mL': -3.4, 'pH': -3.5, 'kW': -2.9}
TOOL_TAGS = {'<tool_response>': -1.23, '</tool_call>': -0.4}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    if token in TOOL_TAGS:
        return None, TOOL_TAGS[token]
    if token.strip() == 'README':
        return None, -1.32 if token.startswith(' ') else -0.52
    match = CAMEL_WORD.search(token)
    if not match:
        acronym_name = re.search(r'[A-Z]{2,}[a-z]{2,}', token)
        return None, -1.3 if acronym_name else 0.0

    word = match.group()
    parts = PARTS.findall(word)
    first = parts[0].lower()
    lower = word[0].islower()
    tail_length = sum(map(len, parts[1:]))
    value = -4.2 + 0.12 * min(tail_length, 18) if lower else -1.3
    if token.startswith('.'):
        value += 0.65 if lower else 0.55
    elif token[0].isspace():
        value += -0.6 if lower else 0.3
    elif not token[0].isalpha():
        value += 0.7 if lower else 0.6

    value += OPERATIONS.get(first, (0.0, 0.0))[0 if lower else 1]
    if first in PREDICATES:
        value -= 1.5 if lower else 0.9
    elif first in {'assert', 'expect'} and lower:
        value += 1.2
    elif first in MUTATIONS and not lower:
        value -= 1.1
    elif first in {'mc', 'mac'} and not lower:
        value += 0.9
    if lower:
        if re.search(r'[A-Z]{2,}', word):
            value += 1.7
        if first in {'i', 'e'} and len(word) > 3:
            value += 1.7
        if re.fullmatch(r'[a-z][A-Z]', word):
            value = SHORT_UNITS.get(word, -4.3)
        elif re.fullmatch(r'[km][A-Z][a-z]', word):
            value = -1.8
    return None, min(0.0, value)

