"""Sparse detector of lookup vocabulary and search/result-list phrases.

Positive responses cover matching, filters, 'search results', 'sort by',
listing headings, and numeric view counts. A Q: opener, check mark and
three chat-protocol cases are also recognized. Unrelated lexical effects
are omitted. Recent text and position reset at every document boundary.
"""
import re

READS = ()
FILTERS = {'filter', 'filters', 'filtered', 'filtering'}
KEYS = {
    'sort': 0.85,
    'filter': 0.62,
    'sorted': 0.45,
    'order': 0.28,
}
OPENERS = {
    'show': 0.72,
    'search': 1.05,
    'browse': 0.85,
    'filter': 0.85,
    'filters': 0.85,
    'articles': 0.85,
    'results': 0.98,
}
LOOKUP = re.compile(r'\b(search|filter|filters|query)\b')


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        recent, previous, position = '', '', 0
    else:
        _, recent, previous, position = carry
    token = prefix.token_strings[-1]
    word = token.strip().lower()
    prev = previous.strip(' \t\n._-').lower()
    capital = token.lstrip()[:1].isupper()
    value = 0.0
    if word == 'matching':
        value = 0.37
    elif word in {'match', 'matches', 'keyword', 'criteria', 'entries'}:
        value = 0.15
    elif word in FILTERS:
        value = 0.20 if token.startswith(' ') else 0.08
        if capital and recent.endswith('\n'):
            value = 0.55 if word == 'filters' else 0.30
    elif word in {'search', 'searching', 'query', 'sort', 'sorted', 'sorting'}:
        value = 0.10
    elif word == 'browse':
        value = 0.24
    elif word == 'results':
        value = 0.18
        if prev == 'search':
            value = 1.0
        elif prev == 'showing':
            value = 2.0
        elif LOOKUP.search(recent[-70:]):
            value = 0.34
    elif word.strip('_') == 'by':
        value = KEYS.get(prev, 0.0)
    elif word == 'views':
        counted = re.search(r'\d[km]?$', previous.lower())
        value = 0.20 if counted or prev in {'k', 'm'} else 0.01
    elif word == 'showing':
        value = 0.90 if prev == 'now' else (0.65 if capital else 0.02)
    elif word in {'questions', 'topics'}:
        if re.search(r'similar\s*$', recent[-20:]):
            value = 0.45
    elif word == 'result':
        value = -0.05
    elif word == 'order' and prev == 'in':
        value = -0.075
    elif word == '✓':
        value = 0.125
    if token.startswith(':') and previous == 'Q' and position < 3:
        value = 0.295
    if position == 0:
        value = OPENERS.get(word, value)
        if word == 'showing':
            value = 2.10 if token == 'Showing' else 0.90
    if token == '<|im_start|>':
        value = -0.245 if position == 0 else 0.0
    elif token == '<tool_call>':
        value = -0.166
    elif previous == '<|im_start|>' and word == 'user':
        value = -0.062
    recent = (recent + token.lower())[-160:]
    return (doc, recent, token, position + 1), float(value)

