programs.sol:
"""A current-word signal for works, units of content, objects and services.

Episodes and albums respond most strongly. Books, numbered subdivisions,
biological taxa, objects and services also respond. Some arithmetic and
identity/authentication words have the opposite sign. The noun phrases
'episode of', 'volume of', etc. also give a response on 'of'. This is a
word-form recognizer: it does not infer what the passage is about.
"""
READS = ()
PUNCTUATION = "_.,:;()[]{}<>\"'`/\\-"
UNIT_NOUNS = {
    "book", "books", "volume", "volumes", "vol", "issue", "issues",
    "chapter", "chapters", "species", "genus", "object", "service",
}


def word_value(word, capitalized):
    if word == "episode":
        return 2.9 if capitalized else 2.3
    if word in {"episodes", "isodes"}:
        return 2.1
    if word in {"album", "albums"}:
        return 1.55 if word == "album" else 1.35
    if word in {"volume", "volumes"}:
        return 1.15 if capitalized else 0.96
    if word in {"issue", "issues", "chapter", "chapters"}:
        return 0.9
    if word in {"book", "books"}:
        return 0.74
    if word in {"species", "genus"}:
        return 0.8
    if word in {"object", "service", "服务", "服務", "对象"}:
        return 0.74
    if word in {"objects", "services", "obj", "namespace", "season", "seasons"}:
        return 0.55
    if word == "vol":
        return 0.65
    if word in {"novel", "novels", "lesson", "channel", "documentary"}:
        return 0.45
    if word in {"series", "topic", "topics", "article", "articles", "edition"}:
        return 0.28
    if word == "arithmetic":
        return -0.86
    if word == "auth":
        return -0.78
    if word == "identity":
        return -0.25
    if word in {"math", "geometry", "calculation", "decimal"}:
        return -0.23
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ""
    token = prefix.token_strings[-1].strip().strip(PUNCTUATION)
    word = token.lower()
    value = word_value(word, bool(token and token[0].isupper()))
    if word == "of":
        if previous == "episode":
            value = 1.0
        elif previous in {"episodes", "isodes"}:
            value = 0.72
        elif previous in UNIT_NOUNS:
            value = 0.33
        elif previous in {"album", "albums"}:
            value = 0.45
        elif previous in {"objects", "services", "season", "seasons"}:
            value = 0.18
    return (doc, word), value

programs.haiku:
"""Layer-0 MLP feature for the word 'episode/album/volume/issue/book/service/object...'.

The component is almost a pure lookup on the current token: whether the token is
(a word for) one installment or part of a collection of media or publications
(episode, album, volume, issue, chapter, book, season), or a generic 'service' /
'object' / 'species' type word. It is slightly negative on maths and physics
words (math, geometry, arithmetic, motion, truth). Each token gets a fixed
strength; any other token gets 0.

The strengths are rough averages measured on training text, so the table is
the explanation: nothing is learned beyond these words.
"""

import re

READS = ()

# Media and publication units: strongest on the words for one installment.
MEDIA = {
    "episode": 2.0, "album": 1.5, "volume": 1.0, "vol": 0.6, "issue": 0.9,
    "chapter": 0.9, "book": 0.8, "season": 0.5, "channel": 0.4, "novel": 0.35,
    "documentary": 0.35, "dvd": 0.4, "edition": 0.3, "series": 0.25,
    "article": 0.2, "magazine": 0.2, "posts": 0.3, "artist": 0.25,
}
# Generic nouns: 'service', 'object', and taxonomy words.
GENERIC = {
    "service": 0.8, "object": 0.7, "obj": 0.5, "species": 0.8, "genus": 0.8,
    "namespace": 0.6, "isbn": 0.7, "topic": 0.3,
}
# Maths and physics words: a small negative.
MATH = {
    "math": -0.2, "geometry": -0.4, "arithmetic": -0.9, "motion": -0.3,
    "truth": -0.5, "decimal": -0.2, "calculation": -0.25,
}


def _strength(token: str) -> float:
    word = re.sub(r"[^a-z]", "", token.lower())
    for key in (word, word[:-1] if word.endswith("s") else word):
        for table in (MEDIA, GENERIC, MATH):
            if key in table:
                return table[key]
    return 0.0


def step(carry, prefix, upstream):
    # The activation depends on the current token only.
    return None, float(_strength(prefix.token_strings[-1]))

