programs.sol:
"""A detector for the written numeral 2, not the English word 'two'.

Its main response is local: digit 2, including inside a longer number.
Document-initial twos are especially strong. Digits within a number and
caret exponents are weaker, while hexadecimal byte escapes are stronger.
A short document-position bonus decays with distance from the start.
Other representations of 2, selected numeric terms, and second-position
calendar associations are positive; third/fourth forms are weakly negative.
Unlisted tokens give zero. Small unrelated lexical responses are omitted.
"""
READS = ()

# Numeric terms, rather than an arbitrary vocabulary lookup.
NUMBER_TERMS = {
    'twenty': 0.70, 'twentieth': 0.35, 'twelve': 0.27,
    'binary': 0.37, 'tuesday': 0.30, 'feb': 0.20,
    'third': -0.28, 'fourth': -0.22, 'iii': -0.28,
    'three': -0.13, 'thirty': -0.15,
}


def step(carry, prefix, upstream):
    s = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        pos, prev, tail, initial_twos = 0, '', '', True
    else:
        _, pos, prev, tail, initial_twos = carry
    initial_twos = initial_twos and s == '2'
    word = s.strip().lower()
    value = 0.0
    if s == '2':
        value = 0.90
        if initial_twos:
            value = 3.30
        elif '^' in prev:
            value = 0.16 if prev.endswith('^') else 0.60
            if prev.endswith((')^', ']^')):
                value = 0.04
        else:
            if prev.isdigit():
                value = 0.58 if prev == '1' else 0.70
            elif prev == '.':
                value = 0.73
            elif prev.isspace():
                value = 0.87
            elif prev.endswith(('/', '/(', '(-')) or prev.strip() == '-':
                value = 1.00
            elif (len(prev.strip()) == 1 and prev.strip().isascii()
                  and prev.strip().isalpha()):
                value = 0.96
            if tail.lower().endswith('\\xc'):
                value = 1.74
            elif tail.lower().endswith('\\xe'):
                value = 1.33
            value += 0.47 / (pos + 1) ** 0.5
    elif s == '₂':
        value = 0.89
    elif s == '２':
        value = 0.80
    elif s == '²':
        value = 0.49
    elif s == '二':
        value = 1.68
    elif '二' in s:
        value = 0.80 if s == '第二' else 0.55
    elif word == 'second':
        value = 0.41 if s[:1].isspace() else 0.24
    elif word == 'february':
        value = 0.51 if s[:1].isspace() else 0.37
    elif s.strip() == 'II':
        value = 0.20 if s[:1].isspace() else 0.12
    elif s == '³':
        value = -0.30
    else:
        value = NUMBER_TERMS.get(word, 0.0)
    return (doc, pos + 1, s, (tail + s)[-8:], initial_twos), value

