"""Simplest version: the digit 2 fires; an exponent 2 (after "^") does not."""

READS = ()


def step(carry, prefix, upstream):
    if prefix.token_strings[-1] != "2":
        return carry, 0.0
    if len(prefix.token_ids) == 1 or prefix.document_ids[-2] != prefix.document_ids[-1]:
        return carry, 3.3
    if prefix.token_strings[-2].endswith("^"):
