    return carry, 0.86

programs.luna:
"""Recognize words about finding, seeking, searching, and requesting.

Search and request words get stronger negative predictions than need/want
words. 'For' gets a smaller prediction only after a search-like verb.
"""
READS = ()

FINDING = {
    "find", "finds", "finding", "findings",
    "seek", "seeks", "seeking", "sought",
    "search", "searches", "searching", "searched",
    "cherche", "chercher", "recherche", "recherchent", "suchen",
}
CJK_FINDING = {"找", "寻找", "找寻", "寻", "寻求", "搜索", "搜", "查找", "寻觅"}
NEEDING = {
    "need", "needs", "needed", "needing", "want", "wants", "wanted",
    "wanting", "require", "requires", "required", "requiring",
    "requirement", "necessary", "需要", "需求", "要求", "想要", "希望",
}
AFTER_SEARCH = {
    "look", "looks", "looking", "looked", "hunt", "hunting", "hunted",
    "probe", "probing", "probed", "search", "searching", "seek", "seeking",
}
PUNCTUATION = " \t\r\n.,;:!?()[]{}<>\"'`*_#/"


def clean(token):
    return token.lower().strip(PUNCTUATION)


def step(carry, prefix, upstream):
    current = clean(prefix.token_strings[-1])

    # Subword pieces such as the 'find' in 'Confindustria' also respond.
    if current in CJK_FINDING or current == "求" or current == "要求":
        return None, -1.0
    if current in FINDING or any(
        current.startswith(root) for root in ("find", "seek", "search")
    ):
        return None, -0.9
    if current == "found":
        return None, -0.6
    if current in NEEDING:
        return None, -0.4

    # French 'chercheurs' may be split into 'cherche' + 'urs'.
    start = max(0, len(prefix.token_strings) - 4)
    same_document = [
        prefix.token_strings[i]
        for i in range(start, len(prefix.token_strings))
        if prefix.document_ids[i] == prefix.document_ids[-1]
    ]
    if current.endswith("urs") and "cherche" in "".join(same_document).lower():
        return None, -0.6

    if current == "for":
        preceding = {
            clean(prefix.token_strings[i])
            for i in range(max(0, len(prefix.token_strings) - 5), len(prefix.token_strings) - 1)
            if prefix.document_ids[i] == prefix.document_ids[-1]
        }
        if preceding & AFTER_SEARCH:
            return None, -0.5
    return None, 0.0

programs.sol:
"""Names and labels, especially in structured text.

Training examples showed strong negative responses to names and markup
labels. This approximation detects 'name', compound name identifiers, and
common HTML tag names. Quoted object keys strengthen the name response. Opening
JSON quotes are negative, unlike prose quotes. HTML class assignments have
positive polarity except inside span tags. Small syntax rules also cover
reference types and CSS text alignment; other tokens default to zero.
"""
import re

READS = ()
HTML_TAGS = set('''a abbr b blockquote body br button caption code col div em
fieldset font form h1 h2 h3 h4 h5 h6 head hr html i iframe img input label li
link meta ol option p param pre script section select small span strong style
sub summary sup table tbody td textarea th thead title tr ul'''.split())


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous, in_span = ('', False)
    if carry is not None and carry[0] == doc:
        _, previous, in_span = carry
    token = prefix.token_strings[-1]
    raw = token.strip()
    word = raw.lstrip('._-/([><\'"')
    lower = word.lower()
    p = previous.strip()
    value = 0.0

    if lower in {'name', 'names'}:
        value = -0.73 if lower == 'names' else -0.98
        if word == 'NAME':
            value = -0.8 if raw.startswith('_') else -1.28
        elif raw.startswith('-'):
            value = -1.6
        elif token == 'name':
            value = -2.0 if previous.endswith(('{"', "{'")) else -1.3
        elif token == ' name' and p in HTML_TAGS | {'given'}:
            value = -1.35
    elif raw == 'className' and token[:1].isspace():
        value = 0.6
    elif lower.endswith(('name', 'names')) or lower in {'named', 'renamed', 'rename'}:
        value = -0.3
    elif raw in {'名', '名称', '名叫', '名为', '名為'}:
        value = -0.8 if raw == '名' else -0.6
    elif lower == 'title':
        value = -0.45
    elif lower in {'label', 'description', 'summary', 'ref', 'type'}:
        value = -0.2

    is_tag = word in HTML_TAGS and (
        re.search(r'</?$', previous) or raw.startswith('<'))
    if is_tag:
        value = -0.65
        if word in {'span', 'td'}:
            value = -1.65
        elif word in {'tbody', 'thead'}:
            value = -2.0
        elif word in {'tr', 'title', 'font', 'code'}:
            value = -1.15
        elif word in {'div', 'p', 'a', 'br'}:
            value = -0.4
        if raw.startswith('<'):
            value = -2.0 if word in {'td', 'tbody', 'thead'} else -1.1
    elif raw == 'class' and in_span:
        value = -1.6
    elif raw == 'href' and p.lstrip('<') == 'a':
        value = -1.3
    elif re.fullmatch(r'=\\*"', raw):
        if p == 'className':
            value = 2.0
        elif p == 'class':
            value = -0.25 if in_span else 1.1
        elif p in {'name', 'href', '-type', 'cref', 'src'}:
            value = -0.6
    elif in_span and raw == '">':
        value = -1.4
    elif in_span and raw.isalpha() and previous.endswith('"'):
        value = -0.65
    elif token == '-type' and p == 'ref':
        value = -1.2
    elif token == '-align' and previous.endswith('text'):
        value = -1.45
    elif token.startswith(' "') and token.count('"') == 1:
        value = -0.03
        if previous.endswith('":'):
            value = -0.67
        elif previous.endswith('",'):
            value = -0.48
        elif previous.isspace():
            value = -0.28
        elif p in {'=', ':'}:
            value = -0.14
    elif raw in {'<', '</'}:
        value = 0.15
    elif raw in {"'<", '"<', '"</'}:
        value = 0.35

    if is_tag:
        in_span = word == 'span'
    if '>' in token or '<' in token and not is_tag:
        in_span = False
    return (doc, token, in_span), float(value)

programs.luna:
"""Mark names and quoted field labels in structured text and tool calls."""

READS = ()


def step(carry, prefix, upstream):
    tokens = prefix.token_strings
    token = tokens[-1]
    word = token.strip().lower()

    # Serialized objects often put a name first, then quote each field value.
    if word == "name" and len(tokens) > 1 and tokens[-2].strip().startswith("{"):
        return None, -2.0
    if token.strip().startswith('"') and len(tokens) > 1:
        previous = tokens[-2]
        if previous.rstrip().endswith((':', ',')):
            return None, -0.6

    # Name words, person placeholders, and the Chinese character for a name.
    if "名" in token:
        return None, -0.9
    if "name" in word or "surname" in word:
        if token.strip().isupper():
            return None, -1.25
        if word in {"name", "names", ".name"}:
            return None, -0.9
        return None, -0.55

    # A linking verb can finish a short phrase that identifies a person.
    if word in {"is", "was"}:
        if "name" in "".join(tokens[-7:]).lower():
            return None, -0.65

    # Common names for labels and identifiers in markup or records.
    if word in {"href", "id", "-type", "file_text", "identity"}:
        return None, -0.45

    # Markup delimiters can introduce a field or a control.
    if token.strip() in {"<", "</"}:
        before = "".join(tokens[-6:-1]).lower()
        if any(mark in before for mark in (">", "\n", " />", "</")):
            return None, 0.35

    return None, 0.0

programs.sol:
"""A sparse spelling-sensitive response to Chinese UTF-8 fragments.

After a token containing a space and the UTF-8 lead byte E7, the next
single byte selects a band of CJK characters (U+7000--U+7FFF). The
response is usually negative, with a positive silk-character band.
A few complete Chinese words also have large negative responses.
English lexical families and a few document-opening forms receive small
corrections. Everything else is approximated by zero.
"""

READS = ()

# Individual lexical peaks, written as words rather than vocabulary IDs.
LEXICAL_PEAKS = {
    "玩": -0.56,       # play
    "穿": -0.62,       # wear / pass through
    "灰": -0.85,       # ash / gray
    "灰色": -0.70,     # gray color
    "碎": -0.62,       # shatter
    "翻": -0.44,       # turn over
    "猜": -0.49,       # guess
    "灌": -0.54,       # pour / irrigate
    "粘": -0.48,       # stick
    "矩": -0.44,       # carpenter's square
    "矿泉水": -0.60,   # mineral water
}


def continuation_byte(token_id):
    """Decode the tokenizer's single-byte UTF-8 continuation alphabet."""
    if 222 <= token_id <= 254:
        return token_id - 94       # bytes 80--A0
    if 94 <= token_id <= 105:
        return token_id + 67       # bytes A1--AC
    if token_id == 255:
        return 0xAD
    if 106 <= token_id <= 123:
        return token_id + 68       # bytes AE--BF
    return None


def fragment_response(byte):
    # Each second byte of E7 selects a 64-codepoint CJK spelling band.
    if byte in (0x81, 0xBD, 0xBF):  # fire, net, and feather bands
        return -0.92
    if byte == 0xB5:               # a traditional silk-character band
        return 0.52
    if byte in (0x8C, 0x8E, 0xA2, 0xA6, 0xAA, 0xAF, 0xB2):
        return -0.56
    if byte in (0xAD, 0xB0, 0xB6):
        return 0.05
    if byte in (0x80, 0x8D, 0x97, 0x98, 0xA8, 0xA9,
                0xAE, 0xB4, 0xBA, 0xBE):
        return -0.10
    return -0.32


def english_response(word):
    """Small lexical families; no claim that all English words share these effects."""
    text = word.strip()
    lower = text.lower()
    if lower == "privacy":
        return -0.32
    if lower in ("achieve", "achieved", "achieving"):
        return 0.145
    if lower == "achievement":
        return 0.10
    if lower in ("study", "studies"):
        return 0.085
    if lower == "studying":
        return 0.04
    if text in ("gray", "grey", "grayscale"):
        return -0.17
    if text == "crazy":
        return -0.24
    # Coarse calendar units, with weaker plural week/year responses.
    if lower in ("month", "months"):
        return -0.08
    if lower in ("week", "year"):
        return -0.055
    if lower in ("weeks", "years"):
        return -0.016
    if lower in ("first", "last", "previous"):
        return -0.045
    if lower in ("between", "within"):
        return -0.052
    if text in ("they", "them", "their", "our"):
        return -0.03
    if word == "'s":
        return -0.025
    if word == "'m":
        return -0.065
    if word == "ly":
        return -0.045
    if word == "\\n":
        return 0.034
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_ids[-1]
    word = prefix.token_strings[-1]
    value = LEXICAL_PEAKS.get(word, english_response(word))
    byte = continuation_byte(token)
    if carry == (doc, True) and byte is not None:
        value = fragment_response(byte)
    if carry is None or carry[0] != doc:
        if word and not word.strip("#"):
            value = -0.223
        elif word in ("What", "How", "Why", "Is", "Does"):
            value = -0.23
        elif word in ("Please", "Welcome", "This", "You"):
            value = -0.21
        elif word in ("import", "package", "from", "using", "#include"):
            value = -0.12
        elif (len(word) > 1 and word.isascii() and word.isalpha()
              and word[0].isupper() and not word.isupper()):
            value -= 0.04
    # 10236 is the byte fragment b" \xe7", not a complete character.
    return (doc, token == 10236), float(value)

programs.haiku:
"""Layer-0 MLP down-projection, component 5365.

What it does: this component is nearly silent almost everywhere. Its activation is
dominated by a sparse set of tokens that push it negative, and the program predicts a
fixed value for each listed token and 0 elsewhere. The listed tokens fall into rough
groups:
  - colours: 灰 (grey), 粉 (pink), 紫 (purple), 绿 (green)
  - breaking and damage: 碎 (shatter), 砸 (smash), 破 (break), 烂 (rotten), 剪 (cut),
    砖 (brick), 撕 (tear), 掰 (snap), 炸 (blow up)
  - fire and heat: 火 (fire), 炎 (blaze), 烫 (scald), 灼 (burn), 煎 (fry), 烧 (burn)
  - wild or crazy: 疯 (mad), 狂 (wild), 疯狂 (crazy), 狂欢 (carnival), English " crazy"
  - verbs and nouns: 玩 (play), 玩具 (toy), 玩法 (way of playing), 穿 (wear),
    猜 (guess), 粘 (stick), 翻 (flip), 灌 (pour into), English " privacy"
Separately, the English word " of" is pushed positive after math words (derivative,
terms, equation) and slightly negative after quantity or death words (per cent,
sample, died). The values are rough averages of the measured activations.
"""

READS = ()

COLOUR = {"灰": -0.6, "灰色": -0.6, "粉": -0.35, "紫": -0.3, "紫色": -0.3, "绿": -0.2}
