             "粘": -0.47, "翻": -0.43, "灌": -0.55, " privacy": -0.31, " Privacy": -0.36}
VALUES = {**COLOUR, **BREAK, **FIRE, **WILD, **PLAY_WEAR}
MATH_BEFORE_OF = {" derivative", " terms", " equation", " limit", " expression", " density"}
QTY_BEFORE_OF = {" per", " cent", " sample", " died", " thousands", " millions", " share"}


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
