programs.sol:
"""Local continuation of a closed expression, especially a parenthesis.

Predict a negative pulse for operators, powers, function-body braces and
signature suffixes after a closing delimiter. English linking words have
smaller pulses. Braces have an additional weak local response. One space
or a power sign can bridge to a following number; newlines usually reset
the pulse. Small background lexical fluctuations are not represented.
"""

import unicodedata

READS = ()
LINKS = {
    'and': 0.37, 'or': 0.81, 'is': 0.35, 'for': 0.33,
    'as': 0.59, 'be': 0.55, 'of': 0.12, 'in': 0.11,
    'was': 0.10, 'that': 0.11,
}
# Recognizable syntax classes, not a vocabulary lookup table.
SYNTAX = (
    ({'->', '=>', 'const', 'throws'}, 2.40),
    ({'return', 'continue', 'override', 'null', '_'}, 1.60),
    ({'=', '==', '+', '-', '/', '*', ':', '(', '['}, 1.50),
    ({'!=', '!==', '===', '<', '<=', '>', '>=', '&', '&&', '%'}, 1.15),
    ({'|', '||', '?', '??', '<<'}, 0.75),
    ({'--', '-->', '—', '–', '−', '→'}, 1.25),
    ({'bool', 'int', 'string', 'str', 'float', 'byte', 'error'}, 0.90),
)


def brace(s, after=False):
    if '\n' in s:
        return (0.62 if '\n\n' in s else 0.82) if after else 0.10
    if '\\' in s:
        return 1.48 if after else 0.26
    if not after and ('"' in s or "'" in s):
        return 0.50
    return 1.30 if after else 0.35


def continuation(s):
    word = s.strip()
    if s.startswith('<|'):
        return 0.0
    if s.startswith(' {'):
        return brace(s, True)
    if word in LINKS:
        return LINKS[word]
    for words, size in SYNTAX:
        if word in words:
            return size
    if word.startswith('^') or word in {'²', '³', '**'}:
        return 1.40 if s.startswith(' ') else 2.50
    if word.startswith(('(', '[')):
        return 1.30
    if word.startswith(('=', '+', '-', '*', '/')):
        return 1.40
    if word.startswith(('{', ':\\')):
        return 1.60
    if s.startswith('\\') or s == ' \\':
        return 1.87 if s == '\\' else 1.30
    if s.isspace() and not s.startswith('\n'):
        return 1.63 if '\xa0' in s else 0.95
    if word.isdigit():
        return 1.80 if word == '2' else 1.50
    if len(s) == 1 and s.isascii() and s.isalpha():
        return 1.65 if s == 'n' else 0.70
    if len(word) == 1 and unicodedata.category(word) == 'Sm':
        return 1.10
    if word == '\ufffd':
        return 0.69
    return 0.0


def step(carry, prefix, upstream):
    doc, s = prefix.document_ids[-1], prefix.token_strings[-1]
    old, before = ('', '') if carry is None or carry[0] != doc else carry[1:]
    value = -brace(s) if s.startswith(' {') else -0.002
    if s.startswith('{"'):
        value = -0.29
    elif s.startswith('{\n'):
        value = -0.13

    scale = 1.0 if old.endswith((')', '）')) else 0.0
    if old.endswith(']'):
        scale = 0.55
    elif old.endswith('}'):
        scale = 0.33
    if scale:
        size = continuation(s)
        if old.endswith(']') and s.isspace() and len(s) > 1:
            size = 0.25
        if '\n\n' in s and '{' not in s:
            size *= 0.25
        if size:
            value = -scale * size

    if old in {' ', '^'} and before.endswith((')', '）')) and s.isdigit():
        value = -1.20 if s == '2' else -0.83
    if old.endswith((')^', ']^')):
        scale = 0.5 if old.endswith(']^') else 1.0
        if s.isdigit() or s.startswith('{'):
            value = -scale * (1.98 if s == '2' else 1.65)
        elif len(s) == 1 and s.isascii() and s.isalpha():
            value = -scale
    if s == 'n':
        for ending, size in [(')\\', 0.84), (']\\', 0.35), ('}\\', 0.16)]:
            if old.endswith(ending):
                value = -size
    if s == '\\' and old.endswith(');'):
        value = -0.53
    return (doc, s, old), float(value)

programs.luna:
"""Approximate syntax transitions around delimiters in code and formulas."""

READS = ()
OPERATORS = "=+-*/<>!&|"
CLOSERS = ")]}"
OPENERS = "([{"
NONBREAKING_SPACE = "\u00a0"


def step(carry, prefix, upstream):
    raw = prefix.token_strings[-1]
    token = raw.strip()
    previous = ""
    if len(prefix.token_ids) > 1:
        if prefix.document_ids[-2] == prefix.document_ids[-1]:
            previous = prefix.token_strings[-2].rstrip()

    if previous.endswith(tuple(CLOSERS)):
        if NONBREAKING_SPACE in raw:
            return None, -1.0
        if token and token[0] in OPERATORS:
            return None, -1.0
        if token and token[0] in OPENERS:
            return None, -0.8
        if token.startswith("\\"):
            return None, -1.2
        if token and token[0] in "'\"`":
            return None, -0.3
        if token and token[0] in CLOSERS:
            return None, 0.1
        if not token:
            return None, -0.2
        if token[0].isalnum():
            return None, -0.12
        return None, 0.0

    if previous.endswith(tuple(OPENERS)):
        if token and token[0] in OPENERS:
            return None, -0.5
        if token and token[0] in OPERATORS:
            return None, -0.3
    return None, 0.0

programs.sol:
"""Local English impersonal-subject constructions, especially 'it + predicate'.

The pronoun has a modest negative response. Copulas, contracted auxiliaries
and appearance/change verbs shortly after it have a much larger one. Negation
and auxiliaries are handled within a four-token window;
capitalized 'It' is slightly stronger and 'this' is weaker. Personal subjects
have a small positive contrast. Coefficients approximate training averages, not
an exact grammar or a model of long-range context.
"""
import re

READS = ()
BE = {'is': -2.2, 'was': -3.0, 'were': -1.9, 'be': -3.1,
      'been': -3.0, 'being': -1.4, 'am': -1.5}
AUXILIARIES = {'will': -1.0, 'would': -2.0, 'can': -0.15,
               'could': -0.55, 'may': -0.95, 'might': -1.15,
               'must': -0.6, 'should': -0.7, 'shall': -0.7,
               'has': -0.3, 'have': -0.3, 'had': -0.6,
               'do': -0.4, 'does': -0.45, 'did': -0.55}
PREDICATES = {'seem': -3.6, 'look': -2.8, 'appear': -2.8, 'sound': -2.2,
              'feel': -0.9, 'become': -1.5, 'turn': -2.2, 'come': -1.7,
              'take': -2.5, 'follow': -2.0, 'mean': -1.4, 'matter': -1.6,
              'work': -1.1, 'happen': -1.5, 'start': -1.1, 'begin': -1.1}
PAST_ROOTS = {'took': 'take', 'taken': 'take', 'became': 'become',
              'came': 'come', 'felt': 'feel', 'began': 'begin', 'meant': 'mean'}
ADVERBS = set('also only just really always never still now probably truly '
              'therefore often simply already actually certainly generally '
              'usually entirely absolutely definitely highly currently'.split())
UNCERTAINTY = {'maybe', 'perhaps', 'sometimes'}
HANDLING = set('put get take taking took have had made thought found'.split())


def predicate_response(word, previous, age):
    """A word-class response, attenuated by distance from the subject."""
    root = word[:-1] if word.endswith('s') else word
    root = root[:-2] if root.endswith('ed') else root
    root = PAST_ROOTS.get(word, root)
    value = BE.get(word, AUXILIARIES.get(word, PREDICATES.get(root, 0.0)))
    decay = 0.45 ** (age - 1)
    if root in PREDICATES:
        decay = 0.65 ** (age - 1)
    if word == 'seemed':
        value -= 0.6
    if word in {"'s", "'d", "'ll"}:
        value = -3.1 if word == "'s" else -2.25 if word == "'d" else -1.4
    if word.endswith('n') and word[:-1] in BE | AUXILIARIES:
        value = 0.8 * (BE | AUXILIARIES)[word[:-1]]
    if word in ADVERBS or word == 'all':
        value, decay = -0.9, 0.7 ** (age - 1)
    value *= decay
    if word == 'be' and age >= 2:
        value = -2.7 if age == 2 else -1.8
        if age == 2:
            value = {'can': -1.8, 'should': -2.2, 'may': -3.0,
                     'might': -3.2, 'could': -3.0}.get(previous, value)
        if previous == 'to':
            value = -1.1 if age <= 3 else -0.65
        elif age == 3 and previous in {'not', "'t"}:
            value = -2.3
        elif age == 4:
            value *= 0.4
    if word == 'been' and age >= 2:
        value = -3.0 * 0.8 ** (age - 2)
    if word == 'not':
        value = -1.3 if age <= 2 else -0.35
        if age == 2 and previous == 'was':
            value = -1.65
    if word == "'t":
        value = {'isn': -2.05, 'wasn': -2.55, 'can': -0.3,
                 'shouldn': -0.5, 'won': -1.1}.get(previous, -1.3)
        value *= 0.4 ** abs(age - 2)
    if age == 2 and word in {'like', 'true', 'worth', 'evident', 'apparent'}:
        value = -1.3
    if age <= 2 and word == 'up':
        value = -1.1
    if age == 2 and word == 'to' and previous in {'comes', 'came', 'seems', 'appears'}:
        value = -1.4
    if word == 'out' and previous in {'turns', 'turned'}:
        value = -1.8
    if word == 'that':
        value = 0.45
    return value


def step(carry, prefix, upstream):
    doc, token = prefix.document_ids[-1], prefix.token_strings[-1]
    first = carry is None or carry[0] != doc
    _, age, capital, previous, strength = ((doc, 100, 0.0, '', 1.0)
                                           if first else carry)
    word = token.strip().lower().replace('’', "'")
    age += 1
    value = 0.0
    pronoun = re.fullmatch(r'[\W_]*(it|It|IT)', token)
    if pronoun:
        age, strength = 0, 1.0
        capital = 0.28 if pronoun[1] == 'It' else 0.0
        value = -0.5 if token.startswith(' ') else -0.2
        if capital and not token.startswith(' '):
            value = -0.7
        if pronoun[1] == 'IT':
            value = -0.05
        if previous in BE:
            value = -1.4 if previous in {'is', 'be'} else -1.8
        elif previous in UNCERTAINTY | HANDLING:
            value = -1.05
        elif previous in {'for', 'in', 'on', 'from', 'because', 'where'}:
            value = -0.12
        elif previous in {'and', 'to', 'of', 'with', 'when', 'before', 'until'}:
            value = -0.3
        if first:
            value = -2.66 if token == 'It' else -0.8
    elif word == 'this':
        age, capital, strength = 0, 0.0, 0.25
    elif age <= 4:
        value = strength * predicate_response(word, previous, age)
        if value < -0.3:
            value -= capital * 0.7 ** (age - 1)
    elif word in {'is', 'was', "'s"}:
        if previous in {'he', 'she', 'who'}:
            value = 0.7 if previous == 'who' else 0.4
    return (doc, age, capital, word, strength), float(value)

programs.haiku:
"""v8: after a subject 'it', the predicate that follows is pushed strongly negative.

The program tracks whether the current word sits in the predicate of an 'it' subject: an
'it' (also '.It', '"It') opens it, and copulas and seem-type verbs ('was', "'s", 'is', 'seems',
'been', 'be') then get large negative values, while modals, negations and adverbs in the
verb chain ('would', "wasn't", 'not', 'may') get smaller ones. Any other word closes it.
Bare 'it' also gets a mild negative value. Outside an 'it' predicate, 'be'/'been' after a
modal or 'has' get a small negative value."""
READS = ()

IT_WORDS = {"it", "It", "IT"}
STRONG = {"was": -3.1, "is": -2.2, "'s": -3.0, "’s": -3.0, "seems": -3.6, "seem": -3.3,
          "seemed": -3.6, "been": -3.0, "be": -2.6, "looks": -3.0, "look": -2.5, "appears": -3.0,
          "appear": -2.8, "takes": -2.4, "take": -2.2, "took": -2.6, "turns": -2.5, "were": -2.0,
          "became": -2.0, "becomes": -1.5, "comes": -1.7, "sounds": -2.5}
WEAK = {"would": -2.0, "will": -1.0, "may": -1.0, "might": -1.2, "can": -1.0, "should": -0.8,
        "could": -0.6, "must": -0.6, "not": -1.3, "also": -0.9, "only": -0.8, "just": -0.8,
        "really": -1.0, "still": -0.4, "always": -0.5, "has": -0.4, "have": -0.3, "had": -0.6,
        "does": -0.4, "did": -0.4, "'ll": -1.5, "’ll": -1.5, "'d": -1.5, "’d": -1.5}
NEG_CONTRACTIONS = {"wasn", "isn", "hasn", "doesn", "didn", "won", "couldn", "wouldn",
                    "shouldn", "aren", "weren", "can", "hadn"}
NEG_SUFFIX = {"n't", "'t", "’t", "t"}
# words that make a following 'be'/'been' mildly negative
BE_AFTER = {"might", "could", "may", "not", "has", "can", "also", "cannot", "should", "would"}

def _word(s):
    """The word in a token, without leading quotes or punctuation (' It', '.It', '“It' -> 'It')."""
    return s.strip().lstrip('.“"‘(')

def step(carry, prefix, upstream):
    raw = prefix.token_strings[-1]
    w = _word(raw)
    prev = _word(prefix.token_strings[-2]) if len(prefix.token_strings) > 1 else ""
    if len(prefix.token_strings) == 1 or prefix.document_ids[-2] != prefix.document_ids[-1]:
        carry = False
        prev = ""
    if w in IT_WORDS:
        return True, -0.5
    if carry and w in STRONG:
        return True, STRONG[w]
    if carry and w in WEAK:
        return True, WEAK[w]
    if carry and (w in NEG_CONTRACTIONS or w in NEG_SUFFIX):
        return True, -1.2
    if carry:
        return False, -0.3
    if w in ("be", "been") and prev in BE_AFTER:
        return False, -0.4
    return False, 0.0

programs.sol:
"""A spelling-based approximation of an i-ending continuation signal.

Short, unspaced pieces after written i-like vowels are positive, especially
Greek iota; longer pieces weaken exponentially. Repeating the same vowel
usually suppresses the response. Other Greek vowels are weaker. 'Such'
has a separate, nearly context-independent response around 1.1.

Script-specific weights approximate the observed variation, not a full
pronunciation dictionary. NUL separators and separately tokenized accents
are joined to the preceding spelling; trailing replacement characters
from incomplete UTF-8 are ignored when finding its vowel ending.
"""
import math
import unicodedata
from functools import lru_cache

READS = ()


@lru_cache(maxsize=16384)
def ending(token):
    """Return a vowel family for a written token ending."""
    token = token.rstrip('\ufffd')
    if not token:
        return ''
    last = token[-1]
    if last in 'ิี':
        return 'thai'
    if unicodedata.name(last, '').endswith(('VOWEL SIGN I', 'VOWEL SIGN II')):
        return 'indic'
    if last == '이':
        return 'korean'
    if last.lower() == 'й':
        return 'short-i'
    plain = ''.join(c for c in unicodedata.normalize('NFKD', token)
                    if not unicodedata.combining(c)).lower()
    if not plain:
        return ''
    last = plain[-1]
    if last in 'iıɪ':
        return 'latin'
    if last == 'y':
        return 'y'
    if last in 'иі':
        return 'cyrillic'
    if last == 'ы':
        return 'yeru'
    if last in 'ιηυοωεα':
        return last
    if last in 'يی':
        return 'arabic'
    if last in 'イキシチニヒミリィヰ':
        return 'kana'
    if last in 'իი':
        return 'latin'
    if plain.endswith(('ie', 'ij')):
        return 'weak-i'
    if token.lower().endswith('iſ'):
        return 'latin'
    return ''


# Strength, and decrease per additional letter of the continuation.
VOWELS = {
    'latin': (1.20, 0.47),
    'y': (0.30, 1.25),
    'cyrillic': (1.10, 0.70),
    'short-i': (0.55, 0.85),
    'yeru': (0.55, 1.25),
    'ι': (2.95, 0.70),
    'η': (1.55, 0.70),
    'υ': (0.25, 0.70),
    'ο': (0.50, 0.70),
    'ω': (0.35, 0.70),
    'ε': (0.12, 0.70),
    'α': (0.10, 0.70),
    'arabic': (0.80, 0.85),
    'kana': (1.10, 0.65),
    'korean': (0.65, 1.00),
    'thai': (0.70, 1.00),
    'indic': (1.40, 0.70),
    'weak-i': (0.30, 0.70),
}


def continuation(previous, token):
    family = ending(previous)
    if not family or not token or token[0].isspace():
        return 0.0
    strength, decay = VOWELS[family]
    first = token[0]
    if family == 'kana' and not ('\u30a0' <= first <= '\u30ff'):
        return 0.0
    if ending(first) == family:
        return 0.0
    if family == 'η' and unicodedata.normalize('NFD', previous[-1]) != previous[-1]:
        strength *= 0.5
    n = sum(c.isalpha() for c in token)
    if n:
        if family in 'ιηυοωεα':
            simple = unicodedata.normalize('NFD', first).lower()
            if simple[0] in 'αεηιουω':
                strength *= 0.68
            if any(unicodedata.combining(c) for c in simple):
                strength *= 0.75
        if family == 'cyrillic' and first.lower() in 'жшчщй':
            strength *= 0.55
        if first in "'’":
            return 0.73 if token[1:].lower() == 'd' else 0.10
        if first == '.' and token[1:2].islower():
            strength *= 0.12
        elif first in '-_/':
            strength *= 0.60
        elif not first.isalpha() and first != '.':
            strength *= 0.35
        return strength * math.exp(-decay * (n - 1))
    if first == '\ufffd' or unicodedata.category(first).startswith('M'):
        return strength
    if family == 'latin':
        if token.isdigit():
            return 0.42
        if token == '-':
            return 0.65
        if first in '.,:;!?)]}':
            return 0.06
        return 0.22
    return 0.05


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    value = -0.003 + continuation(previous, token)
    if token.strip().lower() == 'such':
        value = 1.10
    # Ignore NULs, and attach separately tokenized combining marks.
    if token == '\x00':
        token = previous
    elif token and all(unicodedata.category(c).startswith('M') for c in token):
        token = previous + token
    elif token == 'ſ' and ending(previous) == 'latin':
        token = previous + token
    return (doc, token), float(value)

programs.haiku:
"""A word fragment that continues a word right after an i-like letter, and the word 'such'.

Fires on a piece of a split word (no leading space) whose previous piece ends in an
i-like vowel: Greek iota/eta, Latin/Cyrillic i, and similar. The shorter the piece, the more it fires.
"""
import math
import unicodedata

READS = ()

# How strongly an i-like final letter of the previous piece drives the component.
I_LIKE = {"ι": 2.5, "η": 1.4, "і": 0.9, "ی": 0.7, "i": 0.6, "и": 0.6, "ı": 0.5, "ы": 0.3}


def _base(ch):
    """Lower-case letter with accents stripped, e.g. 'ί' -> 'ι'."""
    return unicodedata.normalize("NFD", ch)[0].lower()


def step(carry, prefix, upstream):
    s = prefix.token_strings[-1]
    if s.strip().lower() == "such":
        return None, 1.1
    if len(prefix.token_strings) >= 2 and prefix.document_ids[-2] == prefix.document_ids[-1]:
        prev = prefix.token_strings[-2]
        if s[:1].isalpha() and prev[-1:].isalpha():
            weight = I_LIKE.get(_base(prev[-1]), 0.0)
            return None, weight / math.sqrt(len(s))
    return None, 0.0

programs.luna:
"""Approximate sparse words for beneficial choices, improvement, and progress."""
READS = ()


def word_score(word):
    if word.startswith(("optimal", "optimum", "optim")):
        return 1.5
    if word.startswith(("option", "optional")):
        return 0.6
    if word.startswith("preferably"):
        return 1.2
    if word.startswith("prefer"):
        return 0.75
    if word.startswith("better"):
        return 0.7
    if word.startswith("priorit"):
        return 1.5
    if word.startswith("improv"):
        return 0.85
    if word.startswith(("skilled", "precious")):
        return 0.65
    if word.startswith("prior"):
        return 0.45
    if word.startswith("优化"):
        return 2.0
    if word.startswith("优惠"):
        return 2.0
    if word.startswith(("佳", "模范")):
        return 0.6
    if word.startswith(("先", "追")):
        return 0.55
    if word.startswith("стрем"):
        return 0.5
    return 0.0


def step(carry, prefix, upstream):
    """Score quality, improvement, and progress words; remember split English words."""
    doc = prefix.document_ids[-1]
    raw = prefix.token_strings[-1]
    old_doc, previous = carry if carry is not None else (doc, "")
    if old_doc != doc:
        previous = ""

    starts_word = bool(raw) and raw[0].isspace()
    piece = raw.strip().lower()
    latin = piece.isascii() and piece.isalpha()
    if starts_word or not latin:
        current = piece
        previous = ""
    else:
        current = previous + piece

    value = word_score(current)
    if previous and current.startswith(previous):
        if previous.startswith("optim"):
            value = 0.75
        elif previous.startswith("prior"):
            value = 0.2
        elif word_score(previous):
            value = 0.2

    return (doc, current if latin else ""), value

programs.sol:
"""Approximate code-name introductions, using lexical rather than token-id rules.

A space-prefixed identifier after a declaration, type, or import is negative.
Short indices and identifier verbs get stronger responses; English function
words are weaker. Source/destination abbreviations and scientific-library
names also receive negative baselines. Code-opening words at document starts, and joined
continuations of declaration words, are positive. Calibration is approximate:
this does not parse code or reproduce every token's individual response.
"""
READS = ()

# Code classes: words, name response after bare / space-prefixed introducers.
INTRODUCERS = (
    ("int float bool boolean uint String", 1.0, 0.95),
    ("char string byte", 0.95, 0.7),
    ("double", 1.0, 0.45),
    ("long short", 0.45, 0.15),
    ("var const def class struct interface enum namespace", 0.95, 0.7),
    ("let val mut fn func pub", 0.6, 0.55),
    ("function", 0.8, 0.45),
    ("type alias typedef typename", 0.7, 0.4),
    ("import", 0.8, 0.6),
    ("package", 1.0, 0.3),
    ("from using module mod use", 0.6, 0.1),
    ("param", 1.1, 0.75),
    ("public private protected static final new return delete extends", 0.2, 0.15),
    ("for foreach", 0.35, 0.03),
    ("lambda", 0.6, 0.4),
    ("method theorem", 0.6, 0.03),
    ("sub Ref define ifdef ifndef", 0.6, 0.3),
    ("void Object", 0.6, 0.45),
)
KEYWORDS = {w: (bare, spaced) for words, bare, spaced in INTRODUCERS
            for w in words.split()}
FUNCTION_WORDS = set("""
the an this that these those of to in on at by for from with without into and
or but as if then than is are was were be been being has have had can could
should would will may might must not no do does did me us you it its he she
they them we our their his her my your which who what how where when why
there here all any some each every most more less other same such also
""".split())
VERBS = set("""
get set add remove create read write find update load save parse build test
start stop run call init check render handle open close send make convert
""".split())
NOUNS = set("""
name value key data result input output source target node item object parent
child index count length size width height line page position message content
text code config context args options error response request server user file
path
""".split())
LIBRARIES = set(
    "numpy scipy pandas matplotlib seaborn torch tensorflow sklearn".split()
)
TYPE_ENDINGS = tuple("""
Type Class Interface Exception Stream Reader Writer Context View Node List Map
Set Group Point Vector Matrix Result Request Response Status Connection
Declaration Element Color
""".split())
TYPED = set(
    "bool boolean int uint float char String string var const fn func param".split()
)


def name_strength(word, previous):
    if word.isascii() and word.isalpha() and len(word) == 1:
        return 2.3 if word == "i" else 1.4
    if word in FUNCTION_WORDS:
        return 0.6 if previous in TYPED else 0.15
    for words, strength in ((VERBS, 1.5), (NOUNS, 1.3), (LIBRARIES, 1.6)):
        if word in words:
            return strength
    if word in ("src", "dst", "dest", "com", "net", "cn", "br", "uk"):
        return 1.6
    if word in ("java", "javax", "org", "android"):
        return 0.7
    if word in ("Solution", "TreeNode", "ListNode", "main", "toString"):
        return 0.4
    if word in KEYWORDS:
        return 0.9
    if word.startswith("__"):
        return 0.9
    if word.startswith("_"):
        return 1.6
    if word.isascii() and word.isalpha():
        if word.isupper() or word.istitle():
            return 1.1
        if not word.islower():
            return 0.8
        if len(word) <= 3:
            return 1.2
        if word.endswith(("ing", "tion", "ment", "ity", "ly", "ive")):
            return 0.6
        return 1.0 if len(word) <= 6 else 0.8
    return 0.5 if word.startswith(("$", "*", "&", "^")) else 0.04


def step(carry, prefix, upstream):
    doc, token = prefix.document_ids[-1], prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        if token in ("def", "int", "fn", "function", "void", "from"):
            value = 4.6
        elif token in ("import", "const", "class", "string", "static", "private"):
            value = 3.9
        elif token in ("package", "using", "var", "let", "struct", "export", "public"):
            value = 3.2
        elif token in ("type", "namespace", "func"):
            value = 2.7
        elif token in ("#include", "#ifndef", "#define", "theorem"):
            value = 1.5
        elif token and not token.strip(" \t") and len(token) > 1:
            value = 1.7 if len(token) % 4 == 3 and len(token) < 16 else 0.65
        else:
            value = 0.0
    else:
        old = carry[1]
        previous = old.strip().lstrip("(@.,:&#")
        spaced = old.startswith((" ", "\t"))
        strength = KEYWORDS.get(previous, (0.0, 0.0))[int(spaced)]
        if previous.endswith(("_t", "_type")):
            strength = 0.7
        elif previous[:1].isupper() and previous.endswith(TYPE_ENDINGS):
            strength = max(strength, 0.55)
        elif previous.isascii() and previous.isalpha() and previous[:1].isupper():
            if old.lstrip().startswith("("):
                strength = max(strength, 0.5)
            elif not previous[1:].islower() and not previous.isupper():
                strength = max(strength, 0.35)
        elif previous in (">", "[]"):
            strength = 0.16 if previous == ">" else 0.5
        value = 0.0
        word = token.strip()
        if token.startswith(" "):
            value = -strength * name_strength(word, previous)
            if word in ("src", "dst", "dest"):
                value -= 0.42
            elif word in LIBRARIES:
                value -= 0.16
        elif token.isascii() and token.isalpha():
            if previous in ("def", "function"):
                value = 0.27 if spaced else 0.65
            elif previous in KEYWORDS and strength >= 0.4:
                value = 0.15 if spaced else 0.3
            value += {("var", "char"): 1.5, ("type", "alias"): 1.5,
                      ("include", "graphics"): 0.5}.get((previous, token), 0.0)
    return (doc, token), float(value)

programs.luna:
"""Predict sparse activations from a few recurring multilingual token spellings."""
READS = ()

MANDARIN_J_INITIALS = {"吉", "夹", "夾"}
ADJUSTMENT = {"调整", "調整"}

def step(carry, prefix, upstream):
    spelling = prefix.token_strings[-1].strip()
    if spelling.lower().endswith("j") or spelling.endswith("ج"):
        return None, 3.0
    if spelling == "ж" or spelling in MANDARIN_J_INITIALS:
        return None, 0.8
    if spelling in ADJUSTMENT:
        return None, 1.0
    return None, 0.0

programs.sol:
"""Approximate vowel-pair responses at word-internal token boundaries.

Look for a vowel-ending token followed immediately by a vowel-starting token
in the same document. The strongest Latin-letter pairs end in i or u after
an a, e, or o. Pair strengths and small length, case, accent, and suffix
corrections are fitted from training text. Greek diphthongs have separate
strengths; Cyrillic pairs are weaker. Other positions stay near zero.
Only the preceding token is remembered, and document changes reset it.
"""
import unicodedata

READS = ()
VOWEL_LABELS = {
    'a': 'aаαɑ', 'e': 'eеэεηɛœ', 'i': 'iиіι',
    'o': 'oоοω', 'u': 'uуυ', 'y': 'yы',
}
# Rows are the preceding vowel; columns are the new vowel a,e,i,o,u,y.
SEAM_STRENGTH = {
    'a': (1.05, 0.7, 1.58, 0.33, 1.97, 0.42),
    'e': (0.6, 0.55, 1.27, 0.1, 1.6, 0.37),
    'i': (-0.03, 0.11, 0.45, -0.08, 0.22, 0.11),
    'o': (0.83, 0.8, 1.84, 0.7, 1.47, 0.57),
    'u': (0.27, 0.19, 0.61, 0.11, 0.98, 0.17),
    'y': (-0.05, -0.05, 0.11, -0.01, -0.04, 0.13),
}
GRAMMATICAL_ENDINGS = frozenset((
    'ing', 'ings', 'ion', 'ions', 'ation', 'ations', 'able', 'ably',
    'ability', 'ary', 'ies', 'ity', 'ities', 'ize', 'ized',
    'ization', 'izes', 'izing', 'ous',
))


# These six spellings are the conventional Greek two-vowel combinations.
GREEK_PAIRS = {
    'αι': 1.8, 'ει': 2.4, 'οι': 3.7,
    'αυ': 0.9, 'ευ': 1.4, 'ου': 1.45,
}
CLASSICAL_ENDINGS = frozenset(('ic', 'ics', 'ia', 'ism', 'isms'))


def vowel_label(c):
    base = unicodedata.normalize('NFKD', c.lower())[:1]
    for label, letters in VOWEL_LABELS.items():
        if base in letters and base:
            return label
    return ''


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    s = prefix.token_strings[-1]
    previous = carry[1] if carry and carry[0] == doc else ''
    value = -0.0011
    if s and previous:
        a, b = vowel_label(previous[-1]), vowel_label(s[0])
        if a and b:
            script = unicodedata.name(s[0], '')
            if 'GREEK' in script:
                old = unicodedata.normalize('NFD', previous[-1].lower())[0]
                new = unicodedata.normalize('NFD', s[0].lower())[0]
                value = GREEK_PAIRS.get(old + new, 0.1)
                if old == 'ι':
                    value = -0.2 if new == 'α' else -0.4
                elif old == 'ε' and new in 'οω':
                    value = -0.5
                return (doc, s), float(value)
            value = SEAM_STRENGTH[a]['aeiouy'.index(b)]
            value *= (0.0, 0.68, 1.0, 0.83, 0.53)[min(len(s), 4)]
            value *= (1.0, 0.93, 1.0, 0.83)[min(len(previous.lstrip()), 3)]
            # An internal capital often starts a new CamelCase word.
            if s[0].isupper() and previous[-1].islower():
                value *= 0.17
            if (len(unicodedata.normalize('NFD', s[0])) > 1 or
                    len(unicodedata.normalize('NFD', previous[-1])) > 1):
                value *= 0.68
            if s.lower() in GRAMMATICAL_ENDINGS:
                value *= 0.50
            if s.lower() in CLASSICAL_ENDINGS:
                value *= 0.35
            if len(s) == 1:
                if b in 'aeo':
                    value *= 0.55
                elif b == 'u':
                    value *= 1.25
            if 'CYRILLIC' in script:
                value *= 0.75 if b == 'u' else 0.30
    return (doc, s), float(value)

programs.haiku:
"""Candidate 3: graded word-concept lookup for inquiry, hunting and surveillance words."""
READS = ()
# Strongest: investigation words and the fox (about -1.0 to -1.3).
INVESTIGATE = {"investig", "investigate", "investigated", "investigates", "investigating",
               "investigation", "investigations", "investigative", "investigator", "investigators"}
STRONG = {"fox", "foxes", "狐", "调查", "侦查", "监察"}
# Medium: hunting and predator words, detective and inspector words (about -0.4 to -0.8).
MEDIUM = {"hunt", "hunting", "hunted", "hunter", "hunters", "wolf", "wolves", "狼", "猎",
          "mouse", "detective", "fbi", "inspector"}
# Weak: surveillance, probing, policing and scouting words (about -0.15 to -0.35).
WEAK = {"police", "surveillance", "survey", "spy", "scout", "scouts", "chase", "probe",
        "suspect", "suspicion", "monitor", "camera", "dog", "examine", "examination",
        "audit", "inspect", "inspection", "detect", "explore", "pursue"}

def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    if word.startswith("investig") or word in STRONG:
        value = -1.0
    elif word in MEDIUM:
        value = -0.5
    elif word in WEAK:
        value = -0.2
    else:
        value = 0.0
    return carry, value

programs.luna:
"""Predict negative activations from words associated with investigation.

English investig- forms get suffix-sensitive scores; Chinese and Spanish
investigation terms get smaller scores. A short list of weaker cues covers
hunting, browser/interface, animal, and a few other sampled words. The rule is
a sparse lexical approximation, not a contextual explanation of every response.
"""
READS = ()

INVESTIGATION = -1.0
RELATED = -0.52
RELATED_WORDS = frozenset({
    "hunt", "hunting", "hunter", "hunters", "firefox", "explorer",
    "mouse", "spider", "wolf", "desktop", "dop", "escorted", "escort",
})


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1].lower()
    word = token.strip().strip(".,!?;:\"'()[]{}")
    previous_root = bool(carry)
    if len(prefix.document_ids) > 1 and prefix.document_ids[-1] != prefix.document_ids[-2]:
        previous_root = False

    if word in {"investigación", "investigacion"}:
        value = -0.45
    elif "investig" in token:
        if word.endswith("ators"):
            value = -0.82
        elif word.endswith("ator"):
            value = -0.82
        elif word.endswith("ations"):
            value = -0.97
        elif word.endswith("ation"):
            value = -1.16
        elif word.endswith("ating"):
            value = -1.09
        elif word.endswith("ated"):
            value = -0.95
        elif word.endswith("ate"):
            value = -1.05
        else:
            value = -1.0
    elif previous_root and token.startswith(("at", "ation")):
        value = -0.85
    elif word in {"调查", "纪检"}:
        value = -0.65
    elif word in RELATED_WORDS:
        value = RELATED
    else:
        value = 0.0

    return "investig" in token, float(value)
